/**
 * Energy Price Graph – frontend module
 *
 * Adds a dynamic electricity price graph (import and, optionally, export
 * price) to the built-in Home Assistant Energy dashboard. The graph is a
 * standard statistics-graph card that follows the Energy date picker.
 *
 * This file is served and registered by the energy_price_graph integration.
 * Its options are fetched over the websocket API each time the Energy
 * dashboard is built, so changing them needs no browser refresh.
 *
 * How it works: the Energy dashboard views are generated by frontend
 * "strategies" (energy-view-strategy / energy-overview-view-strategy). We hook
 * the custom element registry so we can extend their generate() output before
 * first use. This relies on frontend internals: if a Home Assistant update changes
 * them, the Energy dashboard keeps working, just without the price graph, and
 * the integration shows a repair issue.
 *
 * The pure calculation functions are exported at the bottom for the tests;
 * the browser ignores the exports.
 */

// Defaults. Query parameters on the module URL can override them (useful when
// the script is loaded manually); the integration's options, fetched over the
// websocket API on every dashboard build, take precedence over both.
const params = new URL(import.meta.url).searchParams;
const OPT = {
  entity: params.get("entity") || null,
  exportEntity: params.get("export_entity") || null,
  showExport: params.get("export") !== "0",
  period: params.get("period") || "auto",
  views: (params.get("views") || "electricity,overview").split(","),
  title: params.get("title") || null,
  importName: params.get("import_name") || null,
  exportName: params.get("export_name") || null,
  minmax: params.get("minmax") === "1",
  // smooth | straight | stepped
  line: ["smooth", "straight", "stepped"].includes(params.get("line"))
    ? params.get("line")
    : "straight",
  nowLine: params.get("now_line") !== "0",
  averageLine: params.get("average_line") === "1",
  cheapestHours: Number(params.get("cheapest")) || 0,
  expensiveHours: Number(params.get("expensive")) || 0,
  showHoursCard: params.get("hours_card") !== "0",
  highlightNegative: params.get("negative") !== "0",
  current: params.get("current") !== "0",
  priceColors: params.get("colors") !== "0",
  colorThreshold: Number(params.get("threshold")) || 10,
  average: params.get("average") !== "0",
  savings: params.get("savings") !== "0",
  timing: params.get("timing") !== "0",
  importSurcharge: 0,
  exportSurcharge: 0,
  water: params.get("water") !== "0",
  gas: params.get("gas") !== "0",
  gasViews: (params.get("gas_views") || "gas").split(","),
  gasCheapestHours: Number(params.get("gas_cheapest")) || 0,
  gasExpensiveHours: Number(params.get("gas_expensive")) || 0,
  gasEntity: params.get("gas_entity") || null,
  forecastAuto: params.get("forecast_auto") !== "0",
  forecastImport: params.get("forecast_import") || null,
  forecastExport: params.get("forecast_export") || null,
  forecastGas: params.get("forecast_gas") || null,
  forecastAttribute: null,
  forecastValueKey: null,
};

// Marker key on our card config. The statistics-graph card ignores unknown
// keys, so it is safe to carry it along; we use it to recognise our cards.
const LINE_KEY = "energy_price_graph_line";
// Marker key with the current-price chips to show in the card header.
const NOW_KEY = "energy_price_graph_now";
// Marker key: pick the resolution from the selected date range ("auto_fine").
const FINE_KEY = "energy_price_graph_fine";
// Marker key with the forecast series to draw as dashed lines.
const FORECAST_KEY = "energy_price_graph_forecast";
// Marker key with the extra lines and areas (now, average, cheapest and most
// expensive hours, negative).
const OVERLAY_KEY = "energy_price_graph_overlays";

const TAG = "[energy-price-graph]";
// Version of this module, from the ?v= parameter the loader adds.
const MODULE_VERSION = params.get("v");
const MARK = "__energyPriceInjected";
const LINE_STYLES = ["smooth", "straight", "stepped"];
const FORECAST_PREFIX = "epg-forecast-";
const OVERLAY_PREFIX = "epg-overlay-";
const HOUR = 3600000;
const DAY = 86400000;

/* Small helpers */

function lang(hass) {
  return hass?.locale?.language || hass?.language || "en";
}

/**
 * Property of the energy data collection on the connection. Without a key
 * the Energy date picker card on an ordinary dashboard uses a collection
 * named after the dashboard ("_energy_<url path>"), or "_energy" when the
 * page has no URL path.
 */
function collectionProp(key, panelUrl) {
  if (key) return `_${key}`;
  return panelUrl ? `_energy_${panelUrl}` : "_energy";
}

/** The energy data collection a card follows, if it exists yet. */
function collectionOf(hass, key) {
  const conn = hass?.connection;
  if (!conn) return undefined;
  return conn[collectionProp(key, hass.panelUrl)] || (key ? undefined : conn[collectionProp()]);
}

function esc(text) {
  return String(text ?? "").replace(/[&<>"]/g, (ch) => `&#${ch.charCodeAt(0)};`);
}

function num(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

/** Statistic row start (ms number, ISO string or Date) as a timestamp. */
function toMs(value) {
  if (typeof value === "number") return value;
  if (value instanceof Date) return value.getTime();
  const ms = Date.parse(value);
  return Number.isFinite(ms) ? ms : NaN;
}

/** Local midnight of the day of a timestamp (default: today). */
function localMidnight(ts = Date.now()) {
  const d = new Date(ts);
  d.setHours(0, 0, 0, 0);
  return d.getTime();
}

/**
 * Read the current options from the integration. Called every time the
 * Energy dashboard builds its views, so option changes apply the next time
 * the dashboard is opened, without a browser refresh.
 */
async function loadOptions(hass) {
  let o;
  try {
    const res = await hass.callWS({ type: "energy_price_graph/options" });
    reloadIfOutdated(res?.version);
    o = res?.options;
  } catch (e) {
    return; // integration not loaded (e.g. script used manually): keep URL options
  }
  if (!o) return;
  OPT.period = o.period || "auto_fine";
  OPT.views = Array.isArray(o.views) && o.views.length ? o.views : OPT.views;
  OPT.showExport = o.show_export !== false;
  OPT.minmax = !!o.minmax;
  OPT.line = LINE_STYLES.includes(o.line_style) ? o.line_style : "straight";
  OPT.nowLine = o.show_now_line !== false;
  OPT.averageLine = !!o.show_average_line;
  OPT.cheapestHours = Math.max(0, Math.round(num(o.cheapest_hours)));
  OPT.expensiveHours = Math.max(0, Math.round(num(o.expensive_hours)));
  OPT.showHoursCard = o.show_hours_card !== false;
  OPT.highlightNegative = o.highlight_negative !== false;
  OPT.current = o.show_current !== false;
  OPT.priceColors = o.show_price_colors !== false;
  OPT.colorThreshold = num(o.price_color_threshold, 10) || 10;
  OPT.average = o.show_average !== false;
  OPT.savings = o.show_savings !== false;
  OPT.timing = o.show_timing !== false;
  OPT.importSurcharge = num(o.import_surcharge);
  OPT.exportSurcharge = num(o.export_surcharge);
  OPT.water = o.show_water !== false;
  OPT.gas = o.show_gas !== false;
  OPT.gasViews = Array.isArray(o.gas_views) ? o.gas_views : ["gas"];
  OPT.gasCheapestHours = Math.max(0, Math.round(num(o.gas_cheapest_hours)));
  OPT.gasExpensiveHours = Math.max(0, Math.round(num(o.gas_expensive_hours)));
  OPT.gasEntity = o.gas_entity || null;
  OPT.forecastAuto = o.forecast_auto !== false;
  OPT.forecastImport = o.forecast_import_entity || null;
  OPT.forecastExport = o.forecast_export_entity || null;
  OPT.forecastGas = o.forecast_gas_entity || null;
  OPT.forecastAttribute = o.forecast_attribute || null;
  OPT.forecastValueKey = o.forecast_value_key || null;
  OPT.title = o.title || null;
  OPT.entity = o.import_entity || null;
  OPT.exportEntity = o.export_entity || null;
  OPT.importName = o.import_name || null;
  OPT.exportName = o.export_name || null;
}

/**
 * After an update of the integration an open browser tab still runs the old
 * module. When the installed version differs from the one running here,
 * reload the page once so the loader imports the new module.
 */
function reloadIfOutdated(serverVersion) {
  if (!serverVersion || !MODULE_VERSION || serverVersion === MODULE_VERSION) return;
  const key = `energy-price-graph-reloaded-${serverVersion}`;
  try {
    if (sessionStorage.getItem(key)) return; // reloaded once already: avoid a loop
    sessionStorage.setItem(key, "1");
  } catch (e) {
    return; // no storage: do not risk a reload loop
  }
  console.info(TAG, `updated from ${MODULE_VERSION} to ${serverVersion}, reloading`);
  location.reload();
}

/* ------------------------------------------------------------------------ *
 * Health reports
 *
 * The integration shows a repair issue when the module cannot extend the
 * Energy dashboard (usually after a Home Assistant update changed the
 * frontend internals), and removes it again once it works.
 * ------------------------------------------------------------------------ */

const REPORTED = new Set();
const PATCHED = new Set();

function report(hass, status, view, error) {
  if (!hass?.callWS || REPORTED.has(status)) return;
  // One tab that works must not clear the issue of another tab that failed.
  if (status === "ok" && REPORTED.has("failed")) return;
  REPORTED.add(status);
  hass
    .callWS({
      type: "energy_price_graph/report",
      status,
      ...(view && { view }),
      ...(error && { error: String(error?.message || error).slice(0, 500) }),
      ...(MODULE_VERSION && { version: MODULE_VERSION }),
    })
    .catch(() => {}); // integration not loaded or older: ignore
}

/**
 * When the Energy panel is open but none of the strategies could be patched,
 * the frontend internals have changed. Only report this when the energy
 * settings have a grid source, otherwise the panel may just show its setup.
 */
async function checkActive() {
  if (PATCHED.size || !location.pathname.startsWith("/energy")) return;
  const hass = document.querySelector("home-assistant")?.hass;
  if (!hass?.callWS) return;
  try {
    const prefs = await hass.callWS({ type: "energy/get_prefs" });
    if (!(prefs?.energy_sources || []).some((s) => s.type === "grid")) return;
  } catch (e) {
    return;
  }
  report(hass, "not_active", null, "Energy dashboard strategies not found");
}

/**
 * Find the price sensors (import + export) in the energy preferences.
 * Supports the current schema (entity_energy_price[_export] on the grid
 * source) and the older one (flow_from / flow_to).
 */
async function findPriceEntities(hass) {
  let imp = OPT.entity;
  let exp = OPT.exportEntity;
  let gas = OPT.gasEntity;
  if (!imp || (!exp && OPT.showExport) || (!gas && OPT.gas)) {
    try {
      const prefs = await hass.callWS({ type: "energy/get_prefs" });
      for (const src of prefs?.energy_sources || []) {
        if (src.type === "gas") gas = gas || src.entity_energy_price || null;
        if (src.type !== "grid") continue;
        // current schema
        imp = imp || src.entity_energy_price || null;
        exp = exp || src.entity_energy_price_export || null;
        // older schema
        for (const f of src.flow_from || []) imp = imp || f.entity_energy_price || null;
        for (const f of src.flow_to || []) exp = exp || f.entity_energy_price || null;
      }
    } catch (e) {
      console.warn(TAG, "could not read energy preferences", e);
    }
  }
  if (!OPT.showExport) exp = null;
  return { imp, exp, gas };
}

/** Same colours as grid import / export on the Energy dashboard. */
function themeColor(varName, fallback) {
  try {
    const v = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
    if (/^#[0-9a-f]{3,8}$/i.test(v)) return v;
  } catch (e) { /* ignore */ }
  return fallback;
}

function colors() {
  return {
    import: themeColor("--energy-grid-consumption-color", "#488fc2"),
    export: themeColor("--energy-grid-return-color", "#8353d1"),
    gas: themeColor("--energy-gas-color", "#8e021b"),
    good: themeColor("--success-color", "#43a047"),
    warn: themeColor("--warning-color", "#ffa600"),
    bad: themeColor("--error-color", "#db4437"),
    muted: themeColor("--secondary-text-color", "#727272"),
  };
}

