function labels(hass) {
  const code = lang(hass).split("-")[0];
  // Norwegian: Nynorsk ("nn") and the generic code ("no") use the Bokmål labels.
  const l = LABELS[code === "nn" || code === "no" ? "nb" : code] || LABELS.en;
  return {
    ...l,
    title: OPT.title || l.title,
    imp: OPT.importName || l.imp,
    exp: OPT.exportName || l.exp,
  };
}

const AVG_CARD = "energy-price-average-card";

function averageCard({ imp, exp }, collectionKey, L) {
  const c = colors();
  return {
    type: `custom:${AVG_CARD}`,
    title: L.avgTitle,
    collection_key: collectionKey,
    import_entity: imp || null,
    export_entity: exp || null,
    labels: L,
    show_savings: OPT.savings,
    show_timing: OPT.timing,
    surcharge: { import: OPT.importSurcharge, export: OPT.exportSurcharge },
    colors: { import: c.import, export: c.export },
  };
}

const HOURS_CARD = "energy-price-hours-card";
const GRAPH_CARD = "energy-price-graph-card";

function hoursCard({ imp }, collectionKey, L) {
  const c = colors();
  return {
    type: `custom:${HOURS_CARD}`,
    title: L.hoursTitle,
    collection_key: collectionKey,
    import_entity: imp || null,
    labels: L,
    colors: { cheapest: c.good, expensive: c.warn },
    hide_when_off: true,
  };
}

/**
 * Configuration for a card that was added by hand to a dashboard: built like
 * on the Energy dashboard, with the user's own settings on top. Without a
 * collection_key the card follows the Energy date picker card of that
 * dashboard (the "_energy" collection).
 */
async function standaloneConfig(hass, build, own) {
  await loadOptions(hass);
  const found = await findPriceEntities(hass);
  const L = labels(hass);
  const key = own?.collection_key || undefined;
  const base = build(found, key, L);
  const rest = { ...(own || {}) };
  delete rest.type;
  const cfg = { ...base, ...rest };
  if (!key) delete cfg.collection_key;
  return cfg;
}

/**
 * Electricity tab: average price card directly below Energy distribution,
 * in the sidebar on large screens and in the main column on small screens.
 */
function injectAverage(view, card) {
  // Older frontends: flat card list with a sidebar position.
  if (Array.isArray(view.cards)) {
    const idx = view.cards.findIndex((c) => c.type === "energy-distribution");
    view.cards.splice(idx + 1, 0, { ...card, view_layout: { position: "sidebar" } });
    return;
  }
  const sidebarCards = view.sidebar?.sections?.[0]?.cards;
  if (Array.isArray(sidebarCards)) {
    const idx = sidebarCards.findIndex((c) => c.type === "energy-distribution");
    sidebarCards.splice(idx + 1, 0, card);
    // Small screens: the sidebar is hidden and the strategy repeats its cards
    // as single-column sections; do the same right after Energy distribution.
    const sections = view.sections || [];
    const sIdx = sections.findIndex(
      (s) => s.visibility && (s.cards || []).some((c) => c.type === "energy-distribution")
    );
    const visibility = sIdx !== -1
      ? sections[sIdx].visibility
      : [{ condition: "view_columns", max: 1 }];
    sections.splice(sIdx + 1, 0, { type: "grid", column_span: 1, visibility, cards: [card] });
    return;
  }
  // No sidebar: top of the first section.
  const first = (view.sections || [])[0];
  if (first) first.cards = [card, ...(first.cards || [])];
}

/** Forecast entity: the chosen one, or the price sensor itself (auto). */
function forecastEntity(chosen, priceEntity) {
  return chosen || (OPT.forecastAuto ? priceEntity : null);
}

/** Settings shared by the electricity and gas price graphs. */
function graphCard(title, entities, forecasts, collectionKey, L, hours) {
  const fine = OPT.period === "auto_fine";
  const c = colors();
  return {
    type: "statistics-graph",
    title,
    entities: entities.map(({ entity, name, color }) => ({ entity, name, color })),
    stat_types: OPT.minmax ? ["mean", "min", "max"] : ["mean"],
    chart_type: "line",
    // "auto" is the card's default; leaving the key out keeps older frontends
    // (which do not know "auto") working. "auto_fine" starts at 5 minutes and
    // is adjusted to the selected date range (see patchStatisticsCard).
    ...(fine ? { period: "5minute", [FINE_KEY]: true } : OPT.period !== "auto" && { period: OPT.period }),
    energy_date_selection: true,
    collection_key: collectionKey,
    // A legend is only useful with more than one line.
    hide_legend: entities.length < 2 && !OPT.minmax,
    [LINE_KEY]: OPT.line,
    ...(OPT.current && {
      [NOW_KEY]: entities.map((e) => ({
        entity: e.entity,
        name: e.name,
        color: e.color,
        better: e.better,
        colored: OPT.priceColors,
        threshold: OPT.colorThreshold / 100,
        forecast: forecasts.find((f) => f.reference === e.entity)?.entity || null,
        tooltip: `${L.now}: ${e.name}`,
        todayAvgLabel: L.todayAvg,
      })),
    }),
    ...(forecasts.length && { [FORECAST_KEY]: forecasts }),
    [OVERLAY_KEY]: {
      reference: entities[0]?.entity,
      color: entities[0]?.color,
      now: OPT.nowLine,
      average: OPT.averageLine,
      cheapest: hours.cheapest,
      expensive: hours.expensive,
      negative: OPT.highlightNegative,
      colors: { good: c.good, warn: c.warn, bad: c.bad, muted: c.muted },
    },
    grid_options: { columns: "full" },
  };
}

function priceCard({ imp, exp }, collectionKey, L) {
  const entities = [];
  const forecasts = [];
  const sameEntity = imp && exp && imp === exp;
  const c = colors();
  if (imp) {
    const name = sameEntity ? L.title : L.imp;
    entities.push({ entity: imp, name, color: c.import, better: "low" });
    const f = forecastEntity(OPT.forecastImport, imp);
    if (f) forecasts.push({ entity: f, reference: imp, name: `${name} (${L.forecast})`, color: c.import });
  }
  if (exp && !sameEntity) {
    entities.push({ entity: exp, name: L.exp, color: c.export, better: "high" });
    const f = forecastEntity(OPT.forecastExport, exp);
    if (f) forecasts.push({ entity: f, reference: exp, name: `${L.exp} (${L.forecast})`, color: c.export });
  }
  return graphCard(L.title, entities, forecasts, collectionKey, L, {
    cheapest: OPT.cheapestHours,
    expensive: OPT.expensiveHours,
  });
}

function gasCard(gas, collectionKey, L) {
  const color = colors().gas;
  const f = forecastEntity(OPT.forecastGas, gas);
  const forecasts = f ? [{ entity: f, reference: gas, name: `${L.gas} (${L.forecast})`, color }] : [];
  // Own settings: a gas price is often the same all day, so the cheapest and
  // most expensive hours are off unless asked for.
  return graphCard(L.gasTitle, [{ entity: gas, name: L.gas, color, better: "low" }], forecasts, collectionKey, L, {
    cheapest: OPT.gasCheapestHours,
    expensive: OPT.gasExpensiveHours,
  });
}

/**
 * Older Home Assistant versions build the Energy views as a flat list of
 * cards (masonry / sidebar view) instead of sections.
 */
function injectIntoCards(view, card) {
  if (!Array.isArray(view.cards)) return false;
  const idx = view.cards.findIndex((c) => c.type === "energy-usage-graph");
  view.cards.splice(idx === -1 ? 0 : idx + 1, 0, card);
  return true;
}

/** Electricity tab: card directly after the energy usage graph. */
function injectElectricity(view, card) {
  if (injectIntoCards(view, card)) return true;
  for (const section of view.sections || []) {
    const cards = section.cards || [];
    const idx = cards.findIndex((c) => c.type === "energy-usage-graph");
    if (idx !== -1) {
      cards.splice(idx + 1, 0, card);
      return true;
    }
  }
  // No usage graph (e.g. hidden): put it at the top of the main section.
  const main = (view.sections || []).find((s) => s.column_span === 3);
  if (main) {
    main.cards = [card, ...(main.cards || [])];
    return true;
  }
  return false;
}

/**
 * Summary tab: own section directly after the section with the energy usage
 * graph. Cards injected later end up above earlier ones.
 */
function injectOverview(view, card) {
  if (injectIntoCards(view, card)) return true;
  const sections = view.sections || (view.sections = []);
  const idx = sections.findIndex((s) =>
    (s.cards || []).some((c) => c.type === "energy-usage-graph")
  );
  const newSection = { type: "grid", cards: [card] };
  if (idx !== -1) sections.splice(idx + 1, 0, newSection);
  else sections.push(newSection);
  return true;
}

/**
 * Gas tab: price graph below the gas consumption graph and its totals table,
 * which share a row (2/3 + 1/3), so that row stays intact.
 */
function injectGas(view, card) {
  const after = (cards) => {
    let idx = -1;
    cards.forEach((c, i) => {
      if (c.type === "energy-gas-graph" || c.type === "energy-sources-table") idx = i;
    });
    return idx;
  };
  if (Array.isArray(view.cards)) {
    view.cards.splice(after(view.cards) + 1, 0, card);
    return true;
  }
  for (const section of view.sections || []) {
    const cards = section.cards || [];
    const idx = after(cards);
    if (idx !== -1) {
      cards.splice(idx + 1, 0, card);
      return true;
    }
  }
  const first = (view.sections || [])[0];
  if (first) first.cards = [...(first.cards || []), card];
  return !!first;
}

/** Water tab: card below the water consumption graph and the sources table. */
function injectWater(view, card) {
  const after = (cards) => {
    let idx = -1;
    cards.forEach((c, i) => {
      if (c.type === "energy-water-graph" || c.type === "energy-sources-table") idx = i;
    });
    return idx;
  };
  if (Array.isArray(view.cards)) {
    view.cards.splice(after(view.cards) + 1, 0, card);
    return true;
  }
  for (const section of view.sections || []) {
    const cards = section.cards || [];
    const idx = after(cards);
    if (idx !== -1) {
      cards.splice(idx + 1, 0, card);
      return true;
    }
  }
  const first = (view.sections || [])[0];
  if (first) first.cards = [...(first.cards || []), card];
  return !!first;
}

const TARGETS = {
  "energy-view-strategy": { key: "electricity", inject: injectElectricity },
  "energy-overview-view-strategy": { key: "overview", inject: injectOverview },
  "gas-view-strategy": { key: "gas", inject: injectGas },
  "water-view-strategy": { key: "water", inject: injectWater },
};

/** Add our cards to a generated Energy view. */
async function extendView(target, view, config, hass) {
  await loadOptions(hass);
  const found = await findPriceEntities(hass);
  const key = config?.collection_key || "energy_dashboard";
  const L = labels(hass);
  if (target.key === "water") {
    if (OPT.water) target.inject(view, waterCard(key, L));
    return;
  }
  const showGas = (tab) => OPT.gas && found.gas && OPT.gasViews.includes(tab);
  if (target.key === "gas") {
    if (showGas("gas")) target.inject(view, gasCard(found.gas, key, L));
    return;
  }
  // The average card also works without price sensors (it then shows a
  // fixed price, if configured, as the market value), so it does not
  // depend on the graph being shown.
  if (target.key === "electricity" && OPT.average) {
    injectAverage(view, averageCard(found, key, L));
  }
  // Injected after the average card at the same place, so it ends up above it.
  if (target.key === "electricity" && OPT.showHoursCard && (OPT.cheapestHours > 0 || OPT.expensiveHours > 0)) {
    injectAverage(view, hoursCard(found, key, L));
  }
  // Summary tab: the gas graph goes first, so the electricity graph that is
  // injected next ends up above it.
  if (target.key === "overview" && showGas("overview")) {
    target.inject(view, gasCard(found.gas, key, L));
  }
  if (!OPT.views.includes(target.key)) return;
  if (!found.imp && !found.exp) {
    console.info(TAG, "no price sensor found, no price graph added");
    return;
  }
  target.inject(view, priceCard(found, key, L));
}

function patchStrategy(tag, ctor) {
  const target = TARGETS[tag];
  if (!target) return;
  if (!ctor || typeof ctor.generate !== "function" || ctor[MARK]) return;

  const original = ctor.generate;
  ctor.generate = async function (config, hass, ...rest) {
    const view = await original.call(this, config, hass, ...rest);
    try {
      await extendView(target, view, config, hass);
      report(hass, "ok", target.key);
    } catch (e) {
      console.error(TAG, "injection failed, dashboard left unchanged", e);
      report(hass, "failed", target.key, e);
    }
    return view;
  };
  ctor[MARK] = true;
  PATCHED.add(target.key);
  console.info(TAG, `active on ${target.key}`);
}

// The energy strategies are only loaded when the Energy dashboard is opened.
// We hook the custom element registry so we can patch them before first use:
// - define(): patch when the strategy is registered;
// - get(): the dashboard looks the strategy up right before calling
//   generate(), so patching there is deterministic.
// The frontend may replace window.customElements with a scoped-registry
// polyfill after this module has run, so we (re)install the hooks on every
// registry object we see.
const HOOK = "__energyPriceGraphHooked";
let watching = false;

function installRegistryHooks() {
  const reg = window.customElements;
  if (!reg || reg[HOOK]) return;
  const define = reg.define;
  const get = reg.get;
  try {
    reg.define = function (name, ctor, options) {
      if (name in TARGETS) patchStrategy(name, ctor);
      return define.call(this, name, ctor, options);
    };
    reg.get = function (name) {
      const ctor = get.call(this, name);
      if (ctor && name in TARGETS) patchStrategy(name, ctor);
      return ctor;
    };
    reg[HOOK] = true;
  } catch (e) {
    console.warn(TAG, "could not hook custom element registry", e);
  }
  defineAverageCard(reg, get);
  for (const tag of Object.keys(TARGETS)) {
    const existing = get.call(reg, tag);
    if (existing) patchStrategy(tag, existing);
    reg
      .whenDefined(tag)
      .then(() => patchStrategy(tag, get.call(reg, tag)))
      .catch(() => {});
  }
  reg
    .whenDefined("hui-statistics-graph-card")
    .then(() => patchStatisticsCard(get.call(reg, "hui-statistics-graph-card")))
    .catch(() => {});
  reg
    .whenDefined("ha-chart-base")
    .then(() => patchChartBase(get.call(reg, "ha-chart-base")))
    .catch(() => {});
  if (!watching) {
    watching = true;
    reg
      .whenDefined("ha-panel-energy")
      .then(() => setTimeout(checkActive, 20000))
      .catch(() => {});
  }
}

/* ------------------------------------------------------------------------ *
 * Line style
 *
 * The statistics-graph card always draws line charts smoothed. For prices a
 * stepped line is more accurate (a price holds for the whole period), so we
 * adjust the series right before the chart renders — only for charts that
 * belong to one of our cards.
 * ------------------------------------------------------------------------ */

/** Walk up from a chart to the statistics-graph card that hosts it. */
function hostCard(chart) {
  let node = chart;
  for (let i = 0; i < 6 && node; i++) {
    node = node.getRootNode?.()?.host;
    if (node && node.localName === "hui-statistics-graph-card") return node;
  }
  return null;
}

function lineStyleFor(chart) {
  let node = chart;
  for (let i = 0; i < 6 && node; i++) {
    const root = node.getRootNode?.();
    node = root?.host;
    if (!node) return null;
    const style =
      node._config?.[LINE_KEY] ??
      node.config?.[LINE_KEY] ??
      node.parentElement?.config?.[LINE_KEY];
    if (style) return style;
  }
  return null;
}

function lineShape(style) {
  return { smooth: style === "smooth" ? 0.4 : false, step: style === "stepped" ? "end" : false };
}

function styleSeries(data, style) {
  if (!Array.isArray(data)) return data;
  return data.map((s) => (s && s.type === "line" ? { ...s, ...lineShape(style) } : s));
}

/** Our own series, so they can be removed before they are added again. */
function isOwnSeries(s) {
  const id = String(s?.id || "");
  return id.startsWith(FORECAST_PREFIX) || id.startsWith(OVERLAY_PREFIX);
}

/* ------------------------------------------------------------------------ *
 * Forecast (upcoming prices) as dashed lines
 *
 * Price integrations publish upcoming prices in different attribute formats,
 * e.g. Nord Pool (raw_today / raw_tomorrow: {start, end, value}), ENTSO-e
 * (prices: {time, price}), Zonneplan (forecast: {datetime, electricity_price})
 * or Frank Energie (prices: {from, till, price}). We look for lists of objects
 * with a time and a numeric price and scale the values to the unit of the
 * price sensor. Integrations that offer the prices through an action instead
 * (Nord Pool, Tibber, EnergyZero and easyEnergy in Home Assistant core) are
 * asked through the integration's websocket API.
 * ------------------------------------------------------------------------ */

const TIME_KEYS = ["start", "from", "time", "datetime", "date_time", "start_time", "startsAt", "starts_at", "valid_from", "date", "timestamp"];
const END_KEYS = ["end", "till", "to", "end_time", "endsAt", "ends_at", "valid_till"];
const VALUE_KEYS = ["value", "price", "total", "electricity_price", "price_eur", "marketPrice", "market_price", "price_incl_vat", "energy_price", "gas_price"];

/**
 * Points [timestamp, value] from the attributes of a sensor. With
 * `attribute` only that attribute is read; with `valueKey` only that field
 * is used as the price. Without a known price field, a field is only used
 * when it is the only other number in the item, so an unrelated number (a
 * score, an index) is never drawn as a price.
 */
function forecastPoints(stateObj, attribute = null, valueKey = null) {
  const points = new Map();
  const visit = (value, depth) => {
    if (depth > 2 || !value) return;
    if (Array.isArray(value)) {
      for (const item of value) {
        if (!item || typeof item !== "object" || Array.isArray(item)) continue;
        const tKey = TIME_KEYS.find((k) => item[k] != null);
        if (!tKey) continue;
        const ts = toMs(item[tKey]);
        if (!Number.isFinite(ts)) continue;
        let vKey;
        if (valueKey) {
          vKey = typeof item[valueKey] === "number" ? valueKey : null;
        } else {
          vKey = VALUE_KEYS.find((k) => typeof item[k] === "number");
          if (!vKey) {
            const others = Object.keys(item).filter(
              (k) => !TIME_KEYS.includes(k) && !END_KEYS.includes(k) && typeof item[k] === "number"
            );
            vKey = others.length === 1 ? others[0] : null;
          }
        }
        if (vKey) points.set(ts, item[vKey]);
      }
    } else if (typeof value === "object") {
      for (const v of Object.values(value)) visit(v, depth + 1);
    }
  };
  const attrs = stateObj?.attributes || {};
  const sources = attribute ? [attrs[attribute]] : Object.values(attrs);
  for (const v of sources) visit(v, 0);
  return [...points.entries()].sort((a, b) => a[0] - b[0]);
}

/** Pick the factor (€, ct, €/MWh, 1e-7 € like Zonneplan) closest to the current price. */
function forecastScale(points, reference) {
  const values = points.map((p) => Math.abs(p[1])).filter((v) => v > 0).sort((a, b) => a - b);
  if (!values.length || !(Math.abs(reference) > 0)) return 1;
  const median = values[Math.floor(values.length / 2)];
  let best = 1;
  let bestDiff = Infinity;
  for (const f of [1, 0.01, 0.001, 1e-5, 1e-7]) {
    const diff = Math.abs(Math.log10((median * f) / Math.abs(reference)));
    if (diff < bestDiff) {
      bestDiff = diff;
      best = f;
    }
  }
  return best;
}

// Upcoming prices from the integration's action, per entity:
// { points, at, day, pending, waiters }. Refreshed every 15 minutes.
const ACTION_FORECAST = new Map();

function actionForecast(hass, entity, onLoad) {
  const day = localMidnight();
  let entry = ACTION_FORECAST.get(entity);
  // Without prices (e.g. just after a restart) look again after a minute.
  const maxAge = (entry?.points?.length ? 15 : 1) * 60000;
  const fresh = entry && entry.day === day && entry.at && Date.now() - entry.at < maxAge;
  if (!entry) ACTION_FORECAST.set(entity, (entry = { points: [], waiters: new Set() }));
  if (onLoad) entry.waiters.add(onLoad);
  if (!fresh && !entry.pending && hass?.callWS) {
    entry.pending = true;
    hass
      .callWS({ type: "energy_price_graph/forecast", entity_id: entity })
      .then((res) => {
        entry.points = (res?.points || [])
          .map(([t, v]) => [toMs(t), v])
          .filter(([t, v]) => Number.isFinite(t) && typeof v === "number");
      })
      .catch(() => {
        entry.points = []; // integration not loaded or older
      })
      .finally(() => {
        entry.pending = false;
        entry.at = Date.now();
        entry.day = day;
        const waiters = [...entry.waiters];
        entry.waiters.clear();
        if (entry.points.length) waiters.forEach((fn) => { try { fn(); } catch (e) { /* ignore */ } });
      });
  }
  return entry.points;
}

/** Upcoming prices from the sensor's attributes, or else from the action. */
function forecastFor(hass, entity, onLoad) {
  const attr = forecastPoints(hass?.states?.[entity], OPT.forecastAttribute, OPT.forecastValueKey);
  return attr.length ? attr : actionForecast(hass, entity, onLoad);
}

function withForecast(data, forecasts, hass, style, onLoad) {
  if (!Array.isArray(data) || !hass) return data;
  const out = [...data];
  const now = Date.now();
  forecasts.forEach((f, i) => {
    const points = forecastFor(hass, f.entity, onLoad);
    if (!points.length) return;
    const factor = forecastScale(points, Number(hass.states?.[f.reference]?.state));
    // Start with the period that is running now, so the dashed line connects
    // to the measured line.
    const idx = points.findIndex((p) => p[0] > now);
    const from = idx === -1 ? points.length : Math.max(0, idx - 1);
    const future = points.slice(from).map(([t, v]) => [t, v * factor]);
    if (!future.length) return;
    const ref = data.find((s) => s?.id === `${f.reference}-mean`);
    out.push({
      id: `${FORECAST_PREFIX}${i}`,
      name: f.name,
      type: "line",
      data: future,
      color: f.color,
      itemStyle: { color: f.color },
      lineStyle: { type: "dashed", width: 1.5, color: f.color },
      symbol: "none",
      ...lineShape(style),
      ...(ref?.xAxisIndex != null && { xAxisIndex: ref.xAxisIndex }),
      cursor: "default",
      epgReference: f.reference,
    });
  });
  return out;
}

/* ------------------------------------------------------------------------ *
 * Markers: current time, average price, cheapest and most expensive hours,
 * negative prices
 *
 * The chart only has the line series components of ECharts, so these are
 * drawn as extra line series: a vertical or horizontal two-point line, or a
 * line without stroke whose area is shaded. They are kept out of the tooltip
 * (see wrapTooltip) and the legend (which lists the statistics only).
 * ------------------------------------------------------------------------ */

/** Finite [timestamp, value] points of a series (gaps and nulls removed). */
function seriesPoints(series) {
  const out = [];
  for (const p of series?.data || []) {
    const pair = Array.isArray(p) ? p : p?.value;
    if (!Array.isArray(pair)) continue;
    const t = toMs(pair[0]);
    const v = pair[1];
    if (Number.isFinite(t) && typeof v === "number" && Number.isFinite(v)) out.push([t, v]);
  }
  return out;
}

function medianStep(points) {
  const diffs = [];
  for (let i = 1; i < points.length; i++) diffs.push(points[i][0] - points[i - 1][0]);
  diffs.sort((a, b) => a - b);
  return diffs.length ? diffs[Math.floor(diffs.length / 2)] : HOUR;
}

/** Duration each point's price holds: until the next point, at most `max`. */
function durations(points, max = Infinity) {
  const step = medianStep(points);
  return points.map(([t], i) => Math.min(max, (points[i + 1]?.[0] ?? t + step) - t, step * 4));
}

/** Time-weighted average of points (each price holds until the next point). */
function timeWeightedMean(points) {
  if (!points.length) return null;
  const w = durations(points);
  let sum = 0;
  let total = 0;
  points.forEach(([, v], i) => {
    sum += v * w[i];
    total += w[i];
  });
  return total > 0 ? sum / total : null;
}

/**
 * Start times of the `count` cheapest (or, with `expensive`, the most
 * expensive) hours of each day. Only days of which at least 20 hours are
 * known count, so a day that has only just started is not marked. Hours in
 * `exclude` are skipped, so the cheapest and the most expensive hours never
 * overlap.
 */
function extremeHourSet(points, count, expensive = false, exclude = new Set()) {
  const out = new Set();
  if (!(count > 0) || !points.length) return out;
  const w = durations(points, HOUR);
  const hours = new Map(); // hour start -> { sum, weight }
  points.forEach(([t, v], i) => {
    const h = Math.floor(t / HOUR) * HOUR;
    const b = hours.get(h) || { sum: 0, weight: 0 };
    b.sum += v * w[i];
    b.weight += w[i];
    hours.set(h, b);
  });
  const days = new Map(); // local midnight -> [[hour, avg]]
  for (const [h, b] of hours) {
    if (!(b.weight > 0)) continue;
    const d = localMidnight(h);
    if (!days.has(d)) days.set(d, []);
    days.get(d).push([h, b.sum / b.weight]);
  }
  const order = expensive ? (a, b) => b[1] - a[1] : (a, b) => a[1] - b[1];
  for (const list of days.values()) {
    if (list.length < 20) continue;
    list
      .filter(([h]) => !exclude.has(h))
      .sort(order)
      .slice(0, count)
      .forEach(([h]) => out.add(h));
  }
  return out;
}

/** Start times of the `count` cheapest hours of each day. */
function cheapestHourSet(points, count) {
  return extremeHourSet(points, count);
}

/** Start times of the `count` most expensive hours of each day. */
function expensiveHourSet(points, count, exclude) {
  return extremeHourSet(points, count, true, exclude);
}

/**
 * Data for a shaded area over the points for which `include` is true. Each
 * price holds until the next point, so a run ends at the next point's time.
 */
function runData(points, include) {
  const out = [];
  const step = medianStep(points);
  points.forEach(([t, v], i) => {
    if (!include(t)) return;
    out.push([t, v]);
    const next = points[i + 1];
    if (!next || !include(next[0])) {
      const end = next ? next[0] : t + step;
      out.push([end, v], [end, null]);
    }
  });
  return out;
}

function withOverlays(data, ov, style, now = Date.now()) {
  if (!Array.isArray(data) || !ov) return data;
  const ref =
    data.find((s) => s?.id === `${ov.reference}-mean`) ||
    data.find((s) => s?.type === "line" && !isOwnSeries(s));
  if (!ref) return data;
  const measured = seriesPoints(ref);
  const lastMeasured = measured.length ? measured[measured.length - 1][0] : -Infinity;
  const forecast = seriesPoints(
    data.find((s) => String(s?.id || "").startsWith(FORECAST_PREFIX) && s.epgReference === ov.reference)
  ).filter(([t]) => t > lastMeasured);
  const points = [...measured, ...forecast];
  if (!points.length) return data;

  const out = [...data];
  const x0 = points[0][0];
  const x1 = points[points.length - 1][0] + medianStep(points);
  const hasNegative = ov.negative && points.some(([, v]) => v < 0);
  const values = points.map(([, v]) => v).concat(hasNegative ? [0] : []);
  const yMin = Math.min(...values);
  const yMax = Math.max(...values);
  const c = ov.colors || {};
  const common = {
    type: "line",
    symbol: "none",
    silent: true,
    animation: false,
    cursor: "default",
    tooltip: { show: false },
    ...(ref.xAxisIndex != null && { xAxisIndex: ref.xAxisIndex }),
  };
  const area = (id, series, color) => ({
    ...common,
    ...lineShape(style),
    id: `${OVERLAY_PREFIX}${id}`,
    data: series,
    z: 1,
    lineStyle: { width: 0, opacity: 0 },
    areaStyle: { color, opacity: 0.2 },
  });
  const line = (id, series, color, type, width = 1) => ({
    ...common,
    id: `${OVERLAY_PREFIX}${id}`,
    data: series,
    smooth: false,
    step: false,
    z: 3,
    color,
    lineStyle: { color, type, width, opacity: 0.8 },
  });

  if ((ov.cheapest > 0 || ov.expensive > 0) && medianStep(points) <= HOUR) {
    // Bands from zero to the top of the graph, so they stay visible next to
    // the line and do not mix with the negative-price area.
    const top = yMax > 0 ? yMax : yMin;
    const band = (id, hours, color) => {
      if (!hours.size) return;
      const inside = (t) => hours.has(Math.floor(t / HOUR) * HOUR);
      const data = runData(points.map(([t]) => [t, top]), inside);
      out.push({ ...area(id, data, color), smooth: false, step: false, z: 0 });
    };
    const cheap = cheapestHourSet(points, ov.cheapest);
    band("cheapest", cheap, c.good || "#43a047");
    band("expensive", expensiveHourSet(points, ov.expensive, cheap), c.warn || "#ffa600");
  }
  if (hasNegative) {
    out.push(area("negative", points.map(([t, v]) => [t, Math.min(v, 0)]), c.bad || "#db4437"));
    out.push(line("zero", [[x0, 0], [x1, 0]], c.bad || "#db4437", "solid"));
  }
  if (ov.average) {
    const avg = timeWeightedMean(points);
    if (avg != null) out.push(line("average", [[x0, avg], [x1, avg]], ov.color || c.muted, "dotted", 1.5));
  }
  if (ov.now && now >= x0 && now <= x1 && yMax > yMin) {
    out.push(line("now", [[now, yMin], [now, yMax]], c.muted || "#727272", "dashed"));
  }
  return out;
}

/** Keep the marker series out of the chart's tooltip. */
function wrapTooltip(chart) {
  const opts = chart.options;
  const tooltip = opts?.tooltip;
  if (!tooltip || typeof tooltip.formatter !== "function" || tooltip.formatter[MARK]) return;
  const original = tooltip.formatter;
  const formatter = function (items, ...rest) {
    const shown = Array.isArray(items)
      ? items.filter((p) => !String(p?.seriesId || "").startsWith(OVERLAY_PREFIX))
      : items;
    return original.call(this, shown, ...rest);
  };
  formatter[MARK] = true;
  chart.options = { ...opts, tooltip: { ...tooltip, formatter } };
}

/** Redraw a chart, e.g. when upcoming prices arrived from the integration. */
function refreshChart(chart) {
  if (chart.isConnected && Array.isArray(chart.data)) chart.data = [...chart.data];
}

function patchChartBase(cls) {
  const proto = cls?.prototype;
  if (!proto || proto[MARK]) return;
  const original = proto.willUpdate;
  proto.willUpdate = function (changed) {
    try {
      const card = hostCard(this);
      if (card) queueMicrotask(() => decorateHeader(card));
      const cfg = card && cardConfig(card);
      const style = cfg?.[LINE_KEY] ?? (card ? lineStyleFor(this) : null);
      if (card && style) {
        if (changed?.has?.("options")) wrapTooltip(this);
        if (changed?.has?.("data") && Array.isArray(this.data)) {
          const hass = this.hass || card.hass;
          let data = this.data.filter((s) => !isOwnSeries(s));
          if (style !== "smooth") data = styleSeries(data, style);
          if (Array.isArray(cfg?.[FORECAST_KEY])) {
            data = withForecast(data, cfg[FORECAST_KEY], hass, style, () => refreshChart(this));
          }
          if (cfg?.[OVERLAY_KEY]) data = withOverlays(data, cfg[OVERLAY_KEY], style);
          this.data = data;
        }
      }
    } catch (e) {
      console.warn(TAG, "could not adjust the price graph", e);
    }
    return original?.call(this, changed);
  };
  proto[MARK] = true;
}


/* ------------------------------------------------------------------------ *
 * Current price chips
 *
 * Small chips in the card header (like the kWh total on the energy usage
 * graph) with the current import and export price.
 * ------------------------------------------------------------------------ */

function cardConfig(card) {
  return card?._config ?? card?.parentElement?.config ?? card?.config;
}

function formatPrice(hass, stateObj) {
  const value = Number(stateObj?.state);
  if (!stateObj || !Number.isFinite(value)) return "—";
  const locale = lang(hass);
  const text = new Intl.NumberFormat(locale, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 3,
  }).format(value);
  let unit = stateObj.attributes?.unit_of_measurement || "";
  const m = unit.match(/^([A-Z]{3})\/(.+)$/);
  if (m) {
    try {
      const symbol = new Intl.NumberFormat(locale, {
        style: "currency",
        currency: m[1],
        currencyDisplay: "narrowSymbol",
      })
        .formatToParts(0)
        .find((p) => p.type === "currency")?.value;
      if (symbol) unit = `${symbol}/${m[2]}`;
    } catch (e) {
      /* keep unit as is */
    }
  }
  return `${text} ${unit}`.trim();
}

const CHIP_STYLE =
  "display:inline-flex;align-items:center;gap:6px;white-space:nowrap;" +
  "font-size:var(--ha-font-size-m,14px);font-weight:var(--ha-font-weight-medium,500);" +
  "line-height:20px;letter-spacing:normal;color:var(--primary-text-color);" +
  "padding:var(--ha-space-1,4px) var(--ha-space-2,8px);" +
  "border-radius:var(--ha-border-radius-md,8px);border:1px solid var(--divider-color);";

const LEVEL_COLORS = {
  good: "var(--success-color, #43a047)",
  mid: "var(--warning-color, #ffa600)",
  bad: "var(--error-color, #db4437)",
};

function decorateHeader(card) {
  try {
    const items = cardConfig(card)?.[NOW_KEY];
    if (!Array.isArray(items) || !items.length) return;
    const header = card.shadowRoot?.querySelector(".card-header");
    if (!header) return;

    let box = header.querySelector(".epg-now");
    if (!box) {
      box = document.createElement("span");
      box.className = "epg-now";
      box.style.cssText =
        "display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:center;" +
        "gap:8px;margin-inline-start:auto;margin-inline-end:8px;";
      const link = header.querySelector("a");
      header.insertBefore(box, link && link.parentNode === header ? link : null);
    }

    const hass = card.hass;
    items.forEach((item, i) => {
      let chip = box.children[i];
      if (!chip) {
        chip = document.createElement("span");
        chip.style.cssText = CHIP_STYLE;
        const dot = document.createElement("span");
        dot.style.cssText =
          "width:8px;height:8px;border-radius:50%;flex:none;display:inline-block;";
        const text = document.createElement("span");
        chip.append(dot, text);
        box.append(chip);
      }
      const [dot, text] = chip.children;
      dot.style.background = item.color || "var(--primary-color)";
      const stateObj = hass?.states?.[item.entity];
      const value = formatPrice(hass, stateObj);
      if (text.textContent !== value) text.textContent = value;
      let title = item.tooltip || item.name || "";
      const current = Number(stateObj?.state);
      const stats = item.colored ? todayStats(card, hass, item, current) : null;
      const level = stats ? levelFor(current, stats, item.better, item.threshold ?? 0.1) : null;
      if (level) {
        const color = LEVEL_COLORS[level];
        chip.style.borderColor = color;
        chip.style.background = `color-mix(in srgb, ${color} 14%, transparent)`;
        title += ` — ${item.todayAvgLabel || "average today"}: ${formatPrice(hass, { ...stateObj, state: stats.avg })}`;
      } else {
        chip.style.borderColor = "var(--divider-color)";
        chip.style.background = "";
      }
      chip.title = title;
      chip.setAttribute("aria-label", `${title} ${value}`);
    });
    while (box.children.length > items.length) box.lastElementChild.remove();
  } catch (e) {
    console.warn(TAG, "could not show current price", e);
  }
}

/**
 * How favourable the current price is compared with today: "good", "mid" or
 * "bad". The difference with the average is measured against the average
 * itself or, when prices are close to zero (where a relative difference
 * explodes), against half of today's price range, whichever is larger.
 */
function levelFor(current, stats, better, threshold) {
  if (!stats || !Number.isFinite(current) || !Number.isFinite(stats.avg)) return null;
  const halfRange =
    Number.isFinite(stats.min) && Number.isFinite(stats.max) ? (stats.max - stats.min) / 2 : 0;
  const scale = Math.max(Math.abs(stats.avg), halfRange);
  if (!(scale > 0)) return null;
  let rel = (current - stats.avg) / scale;
  if (better !== "high") rel = -rel; // positive = favourable
  if (rel >= threshold) return "good";
  if (rel <= -threshold) return "bad";
  return "mid";
}

function statsOf(values) {
  if (!values.length) return null;
  return {
    avg: values.reduce((a, b) => a + b, 0) / values.length,
    min: Math.min(...values),
    max: Math.max(...values),
  };
}

// Today's prices per sensor from the recorder (used without a forecast):
// entity -> { day, stats, at, pending }. Refreshed every 15 minutes.
const TODAY_STATS = new Map();

/**
 * Today's average, lowest and highest price. With a forecast the whole day
 * is known (past and upcoming prices), otherwise the recorded prices since
 * midnight are used.
 */
function todayStats(card, hass, item, current) {
  if (!Number.isFinite(current)) return null;
  const start = localMidnight();
  if (item.forecast) {
    const points = forecastFor(hass, item.forecast, () => decorateHeader(card));
    const today = points.filter(([t]) => t >= start && t < start + DAY);
    if (today.length) {
      const factor = forecastScale(today, current);
      return statsOf(today.map(([, v]) => v * factor));
    }
  }
  const cached = TODAY_STATS.get(item.entity);
  const fresh = cached && cached.day === start && cached.at && Date.now() - cached.at < 15 * 60000;
  if (!fresh && !cached?.pending && hass?.callWS) {
    TODAY_STATS.set(item.entity, { ...(cached || {}), pending: true });
    hass
      .callWS({
        type: "recorder/statistics_during_period",
        start_time: new Date(start).toISOString(),
        statistic_ids: [item.entity],
        period: "hour",
        types: ["mean"],
      })
      .then((res) => {
        const vals = (res?.[item.entity] || []).map((r) => r.mean).filter((v) => typeof v === "number");
        TODAY_STATS.set(item.entity, { day: start, stats: statsOf(vals), at: Date.now(), pending: false });
        decorateHeader(card);
      })
      .catch(() => TODAY_STATS.set(item.entity, { day: start, stats: null, at: Date.now(), pending: false }));
  }
  return cached?.day === start ? cached.stats : null;
}

/* "Auto (fine)": choose the resolution from the selected date range. */
const FINE_STATE = new WeakMap(); // card -> { unsub } (fallback only)

function finePeriod(start, end, now = Date.now()) {
  const days = ((end ? end.getTime() : now) - start.getTime()) / DAY;
  const ageDays = (now - start.getTime()) / DAY;
  // 5-minute statistics are kept as long as the recorder keeps history
  // (purge_keep_days, 10 days by default).
  if (days <= 7.5 && ageDays <= 10) return "5minute";
  if (days <= 35) return "hour";
  if (days <= 400) return "day";
  return "month";
}

/**
 * Fallback for frontends without the card's own fetch method (see
 * patchStatisticsCard): follow the date picker ourselves and set the period.
 * This can race with the card's own fetch, so it is only used when needed.
 */
function handleFinePeriod(card) {
  const cfg = cardConfig(card);
  if (!cfg?.[FINE_KEY] || FINE_STATE.has(card) || !card.hass) return;
  const collection = collectionOf(card.hass, cfg.collection_key);
  if (!collection?.subscribe) return; // tried again on the next update
  const state = {};
  FINE_STATE.set(card, state);
  state.unsub = collection.subscribe((data) => {
    if (!card.isConnected) {
      state.unsub?.();
      FINE_STATE.delete(card);
      return;
    }
    if (!data?.start) return;
    const run = (state.run = (state.run || 0) + 1);
    resolveFinePeriod(card, data).then((period) => {
      if (run !== state.run) return; // a newer date range was selected
      state.period = period;
      applyFinePeriod(card, period);
    });
  });
}

/**
 * 5-minute statistics only exist for sensors the recorder samples itself and
 * only for the last purge_keep_days; if there are none for this range, use
 * hourly averages instead of showing an empty graph.
 */
async function resolveFinePeriod(card, data) {
  const period = finePeriod(data.start, data.end);
  if (period !== "5minute") return period;
  const ids = (cardConfig(card)?.entities || []).map((e) => (typeof e === "string" ? e : e.entity));
  try {
    const callWS = card.hass?.callWS ? (msg) => card.hass.callWS(msg) : card._api?.callWS;
    if (!callWS) return "hour";
    const res = await callWS({
      type: "recorder/statistics_during_period",
      start_time: data.start.toISOString(),
      ...(data.end && { end_time: data.end.toISOString() }),
      statistic_ids: ids,
      period: "5minute",
      types: ["mean"],
    });
    const rows = ids.reduce((n, id) => n + (res?.[id]?.length || 0), 0);
    return rows > 0 ? "5minute" : "hour";
  } catch (e) {
    return "hour";
  }
}

function applyFinePeriod(card, period) {
  const current = cardConfig(card);
  if (period && current && current.period !== period && typeof card.setConfig === "function") {
    card.setConfig({ ...current, period });
  }
}

/*
 * The statistics-graph card fetches its statistics itself as soon as the date
 * range changes, with the period in its config at that moment. Changing the
 * period afterwards (from our own date picker subscription) started a second
 * fetch, and whichever answer came last was shown: often the slower 5-minute
 * one, so a month showed only the last 10 days until a hard refresh. Instead
 * we now decide the period inside the card's fetch, before it asks the
 * recorder, and run the fetches of a card one after the other so the newest
 * date range always wins.
 */
const FETCH_STATE = new WeakMap(); // card -> { seq, chain, key, period, pending }

function rangeKey(start, end) {
  return `${start ? start.getTime() : ""}-${end ? end.getTime() : ""}`;
}

/** Period for a date range, cached per card so a repeated fetch does not ask again. */
function finePeriodFor(card, state, start, end) {
  const key = rangeKey(start, end);
  if (state.key === key && state.period) return Promise.resolve(state.period);
  if (state.key === key && state.pending) return state.pending;
  state.key = key;
  state.period = null;
  const pending = resolveFinePeriod(card, { start, end }).then((period) => {
    if (state.key === key) state.period = period;
    return period;
  });
  state.pending = pending.finally(() => {
    if (state.pending === pending) state.pending = null;
  });
  return pending;
}

/** Put the period in the card's config; true when it changed. */
function setCardPeriod(card, period) {
  const current = cardConfig(card);
  if (!period || !current || current.period === period) return false;
  if ("_config" in card) card._config = { ...current, period };
  else if (typeof card.setConfig === "function") card.setConfig({ ...current, period });
  else return false;
  return true;
}

function patchFetch(proto) {
  const original = proto._getStatistics;
  if (typeof original !== "function") return false;
  proto._getStatistics = function (...args) {
    if (!cardConfig(this)?.[FINE_KEY]) return original.apply(this, args);
    let state = FETCH_STATE.get(this);
    if (!state) FETCH_STATE.set(this, (state = { seq: 0, chain: Promise.resolve() }));
    const seq = ++state.seq;
    const run = async () => {
      if (seq !== state.seq) return; // a newer fetch was asked for meanwhile
      const start = this._energyStart;
      let period = "hour"; // no date range (yet): the card shows its default days
      try {
        if (start) period = await finePeriodFor(this, state, start, this._energyEnd);
      } catch (e) {
        console.warn(TAG, "could not choose the resolution", e);
      }
      if (seq !== state.seq) return;
      if (setCardPeriod(this, period)) {
        // The card fetches again by itself when its period changes; only
        // fetch here when it did not.
        await new Promise((resolve) => setTimeout(resolve, 0));
        if (seq !== state.seq) return;
      }
      return original.apply(this, args);
    };
    state.chain = state.chain.then(run, run);
    return state.chain;
  };
  return true;
}

/** Whether a prototype chain already has a hass property (a Lit property). */
function hasHassAccessor(proto) {
  for (let p = proto; p && p !== HTMLElement.prototype; p = Object.getPrototypeOf(p)) {
    const d = Object.getOwnPropertyDescriptor(p, "hass");
    if (d && (d.set || d.get)) return true;
  }
  return false;
}

const HASS = Symbol("energyPriceGraphHass");
const HEADER_QUEUED = Symbol("energyPriceGraphHeaderQueued");

function queueHeader(card) {
  if (card[HEADER_QUEUED]) return;
  card[HEADER_QUEUED] = true;
  queueMicrotask(() => {
    card[HEADER_QUEUED] = false;
    decorateHeader(card);
  });
}

function patchStatisticsCard(cls) {
  const proto = cls?.prototype;
  if (!proto || proto[MARK]) return;
  const fetchPatched = patchFetch(proto);
  // Since Home Assistant 2026.11 the card gets its data from contexts and no
  // longer has a hass property: Lovelace still sets it, but that no longer
  // updates the card, so the current-price chips would stand still. Catch it
  // ourselves to refresh them.
  if (!hasHassAccessor(proto)) {
    Object.defineProperty(proto, "hass", {
      configurable: true,
      get() {
        return this[HASS];
      },
      set(value) {
        this[HASS] = value;
        if (value) queueHeader(this);
      },
    });
  }
  const original = proto.updated;
  proto.updated = function (changed) {
    const result = original?.call(this, changed);
    decorateHeader(this);
    if (!fetchPatched) {
      try {
        handleFinePeriod(this);
        // Lovelace may set the original config again: re-apply our period.
        const state = FINE_STATE.get(this);
        if (state?.period) applyFinePeriod(this, state.period);
      } catch (e) {
        console.warn(TAG, "could not adjust the resolution", e);
      }
    }
    return result;
  };
  const originalDisconnected = proto.disconnectedCallback;
  proto.disconnectedCallback = function () {
    const state = FINE_STATE.get(this);
    if (state) {
      state.unsub?.();
      FINE_STATE.delete(this);
    }
    return originalDisconnected?.call(this);
  };
  proto[MARK] = true;
}

/* ------------------------------------------------------------------------ *
 * Average price card
 *
 * For the period selected in the Energy dashboard:
 *  - "You": what you actually paid / received per kWh = cost ÷ energy, from
 *    the same statistics the Energy dashboard uses (weighted by when you
 *    used or exported energy);
 *  - "Market": the plain average of the price sensor over the period, plus
 *    the surcharge from the options;
 *  - "Timing": share of your import in the cheapest and most expensive
 *    hours of each day.
 * ------------------------------------------------------------------------ */

function currencySymbol(hass) {
  const code = hass?.config?.currency;
  if (!code) return "";
  try {
    return (
      new Intl.NumberFormat(lang(hass), { style: "currency", currency: code, currencyDisplay: "narrowSymbol" })
        .formatToParts(0)
        .find((p) => p.type === "currency")?.value || code
    );
  } catch (e) {
    return code;
  }
}

/** Grid import/export energy and cost statistic ids from the energy prefs. */
function gridStatIds(prefs, info) {
  const out = { from: [], to: [], fixedImport: null, fixedExport: null };
  const fixed = (key, v) => {
    if (typeof v === "number" && out[key] == null) out[key] = v;
  };
  for (const src of prefs?.energy_sources || []) {
    if (src.type !== "grid") continue;
    fixed("fixedImport", src.number_energy_price);
    fixed("fixedExport", src.number_energy_price_export);
    for (const f of src.flow_from || []) fixed("fixedImport", f.number_energy_price);
    for (const f of src.flow_to || []) fixed("fixedExport", f.number_energy_price);
  }
  const cost = info?.cost_sensors || {};
  for (const src of prefs?.energy_sources || []) {
    if (src.type !== "grid") continue;
    // current schema
    if (src.stat_energy_from) {
      out.from.push({ energy: src.stat_energy_from, cost: src.stat_cost || cost[src.stat_energy_from] });
    }
    if (src.stat_energy_to) {
      out.to.push({ energy: src.stat_energy_to, cost: src.stat_compensation || cost[src.stat_energy_to] });
    }
    // older schema
    for (const f of src.flow_from || []) {
      out.from.push({ energy: f.stat_energy_from, cost: f.stat_cost || cost[f.stat_energy_from] });
    }
    for (const f of src.flow_to || []) {
      out.to.push({ energy: f.stat_energy_to, cost: f.stat_compensation || cost[f.stat_energy_to] });
    }
  }
  return out;
}

/**
 * Money per kWh over the period. Only periods in which both the energy and
 * the cost statistic have a value, and energy actually flowed, are counted,
 * so a sensor that was added or repaired halfway through the period does not
 * skew the result. The sign of the cost is kept: at a negative price the
 * cost (or compensation) of that period is negative.
 */
function paidAverage(data, flows) {
  let energy = 0;
  let money = 0;
  for (const f of flows) {
    if (!f.cost) continue;
    const energyRows = data?.stats?.[f.energy];
    const costRows = data?.stats?.[f.cost];
    if (!Array.isArray(energyRows) || !Array.isArray(costRows)) continue;
    const costByStart = new Map();
    for (const r of costRows) {
      if (typeof r?.change === "number") costByStart.set(r.start, r.change);
    }
    for (const r of energyRows) {
      const e = r?.change;
      const c = costByStart.get(r?.start);
      if (typeof e !== "number" || e <= 0 || typeof c !== "number") continue;
      energy += e;
      money += c;
    }
  }
  return energy > 0 ? { avg: money / energy, energy } : null;
}

function marketPeriod(start, end, now = new Date()) {
  const days = ((end || now) - start) / DAY;
  if (days <= 35) return "hour";
  if (days <= 400) return "day";
  return "month";
}

async function marketAverages(hass, start, end, ids) {
  const wanted = ids.filter(Boolean);
  if (!wanted.length) return {};
  const res = await hass.callWS({
    type: "recorder/statistics_during_period",
    start_time: start.toISOString(),
    ...(end && { end_time: end.toISOString() }),
    statistic_ids: wanted,
    period: marketPeriod(start, end),
    types: ["mean"],
  });
  const out = {};
  for (const id of wanted) {
    const vals = (res?.[id] || []).map((s) => s.mean).filter((v) => typeof v === "number");
    out[id] = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
  }
  return out;
}

/**
 * Share of the import energy in the cheapest and the most expensive quarter
 * of the hours of each day. `energy` and `prices` map hour start -> value.
 */
function timingShares(energy, prices) {
  const days = new Map();
  for (const [t, price] of prices) {
    if (typeof price !== "number") continue;
    const d = localMidnight(t);
    if (!days.has(d)) days.set(d, []);
    days.get(d).push([t, price]);
  }
  let cheap = 0;
  let expensive = 0;
  let total = 0;
  for (const hours of days.values()) {
    if (hours.length < 4) continue;
    hours.sort((a, b) => a[1] - b[1]);
    const k = Math.max(1, Math.round(hours.length / 4));
    hours.forEach(([t], i) => {
      const e = energy.get(t) || 0;
      total += e;
      if (i < k) cheap += e;
      if (i >= hours.length - k) expensive += e;
    });
  }
  return total > 0 ? { cheap: cheap / total, expensive: expensive / total, energy: total } : null;
}

async function timingData(hass, start, end, energyIds, priceId) {
  const ids = [...new Set(energyIds.filter(Boolean))];
  if (!ids.length || !priceId) return null;
  const res = await hass.callWS({
    type: "recorder/statistics_during_period",
    start_time: start.toISOString(),
    ...(end && { end_time: end.toISOString() }),
    statistic_ids: [...ids, priceId],
    period: "hour",
    types: ["change", "mean"],
    units: { energy: "kWh" },
  });
  const energy = new Map();
  for (const id of ids) {
    for (const r of res?.[id] || []) {
      if (typeof r.change === "number") energy.set(toMs(r.start), (energy.get(toMs(r.start)) || 0) + r.change);
    }
  }
  const prices = new Map();
  for (const r of res?.[priceId] || []) {
    if (typeof r.mean === "number") prices.set(toMs(r.start), r.mean);
  }
  return timingShares(energy, prices);
}

/**
 * Result compared with the market average, per direction and in total.
 * Import: (market − you) × kWh bought. Export: (you − market) × kWh sold.
 * Positive means better than the market average.
 */
function savings(r) {
  const imp =
    r.importPaid != null && r.importMarket != null && r.importEnergy > 0
      ? (r.importMarket - r.importPaid) * r.importEnergy
      : null;
  const exp =
    r.hasExport && r.exportPaid != null && r.exportMarket != null && r.exportEnergy > 0
      ? (r.exportPaid - r.exportMarket) * r.exportEnergy
      : null;
  const total = imp == null && exp == null ? null : (imp || 0) + (exp || 0);
  return { import: imp, export: exp, total };
}

class EnergyPriceAverageCard extends (globalThis.HTMLElement ?? class {}) {
  setConfig(config) {
    // Lovelace may call setConfig again on an existing card (for example when
    // a view is rebuilt). Keep the last data and recalculate instead of
    // falling back to the loading state, which would otherwise stay until
    // the energy data changes again.
    this._config = config;
    if (!this.shadowRoot) this.attachShadow({ mode: "open" });
    this._render();
    if (this._data && this._hass) this._update(this._data);
  }

  set hass(hass) {
    this._hass = hass;
    if (this.isConnected) this._subscribe();
  }

  get hass() {
    return this._hass;
  }

  connectedCallback() {
    this._subscribe();
  }

  disconnectedCallback() {
    this._unsub?.();
    this._unsub = undefined;
    clearTimeout(this._retry);
    clearTimeout(this._retryMarket);
  }

  getCardSize() {
    return 3;
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }

  static getStubConfig() {
    return {};
  }

  _subscribe() {
    if (this._unsub || !this._hass || !this._config) return;
    if (!this._config.labels) {
      // Added by hand to a dashboard: fill in the rest like on the Energy
      // dashboard (price sensors, labels, colours and options).
      this._autoConfig();
      return;
    }
    const collection = collectionOf(this._hass, this._config.collection_key);
    if (!collection?.subscribe) {
      // The Energy dashboard (or an Energy date picker card) creates the
      // collection; wait until it exists and give a hint after a while.
      clearTimeout(this._retry);
      this._waited = (this._waited || 0) + 1;
      if (this._waited === 10) this._render();
      this._retry = setTimeout(() => this._subscribe(), 500);
      return;
    }
    this._waited = 0;
    this._unsub = collection.subscribe((data) => this._update(data));
  }

  async _autoConfig() {
    if (this._autoPending) return;
    this._autoPending = true;
    try {
      const own = this._config;
      const base = await standaloneConfig(this._hass, (found, key, L) => averageCard(found, key, L), own);
      this._config = base;
      this._render();
      this._subscribe();
    } catch (e) {
      console.warn(TAG, "could not set up the average price card", e);
    } finally {
      this._autoPending = false;
    }
  }

  async _update(data) {
    this._data = data;
    clearTimeout(this._retryMarket);
    const run = (this._run = (this._run || 0) + 1);
    const c = this._config || {};
    const surcharge = c.surcharge || {};
    let result;
    let marketFailed = false;
    try {
      const flows = gridStatIds(data?.prefs, data?.info);
      const imp = paidAverage(data, flows.from);
      const exp = flows.to.length ? paidAverage(data, flows.to) : null;
      result = {
        importPaid: imp?.avg ?? null,
        importEnergy: imp?.energy ?? 0,
        exportPaid: exp?.avg ?? null,
        exportEnergy: exp?.energy ?? 0,
        hasExport: !!c.export_entity || flows.to.length > 0,
        importMarket: flows.fixedImport,
        exportMarket: flows.fixedExport,
        surcharged: false,
        timing: null,
      };
      if (data?.start && (c.import_entity || c.export_entity)) {
        try {
          const market = await marketAverages(this._hass, data.start, data.end, [
            c.import_entity,
            c.export_entity,
          ]);
          // The surcharge only applies to a price sensor, not to a fixed price.
          const withSurcharge = (value, extra) => {
            if (value == null) return null;
            if (extra) result.surcharged = true;
            return value + num(extra);
          };
          if (c.import_entity) {
            result.importMarket = withSurcharge(market[c.import_entity], surcharge.import) ?? result.importMarket;
          }
          if (c.export_entity) {
            result.exportMarket = withSurcharge(market[c.export_entity], surcharge.export) ?? result.exportMarket;
          }
        } catch (e) {
          marketFailed = true;
          console.warn(TAG, "could not load market average, retrying", e);
        }
      }
      if (c.show_timing !== false && data?.start && c.import_entity && marketPeriod(data.start, data.end) === "hour") {
        try {
          result.timing = await timingData(
            this._hass, data.start, data.end, flows.from.map((f) => f.energy), c.import_entity
          );
        } catch (e) {
          console.warn(TAG, "could not calculate timing", e);
        }
      }
    } catch (e) {
      console.error(TAG, "could not calculate average price", e);
      result = { importPaid: null, exportPaid: null, hasExport: false, importMarket: null, exportMarket: null };
    }
    if (run !== this._run) return; // a newer period was selected meanwhile
    result.savings = savings(result);
    this._result = result;
    this._render();
    // The recorder may still be starting (e.g. right after a restart): retry.
    if (marketFailed && this.isConnected) {
      this._retryMarket = setTimeout(() => this._data && this._update(this._data), 15000);
    }
  }

  _fmt(value) {
    if (value == null || !Number.isFinite(value)) return "—";
    const text = new Intl.NumberFormat(lang(this._hass), {
      minimumFractionDigits: 3,
      maximumFractionDigits: 3,
    }).format(value);
    return `${text} ${currencySymbol(this._hass)}/kWh`.trim();
  }

  _pct(value, signed = false) {
    return new Intl.NumberFormat(lang(this._hass), {
      style: "percent",
      maximumFractionDigits: signed ? 1 : 0,
      ...(signed && { signDisplay: "exceptZero" }),
    }).format(value);
  }

  _diff(you, market, higherIsBetter) {
    if (you == null || market == null || !market) return "";
    const rel = (you - market) / Math.abs(market);
    const good = higherIsBetter ? rel >= 0 : rel <= 0;
    return `<span class="${good ? "good" : "bad"}">${this._pct(rel, true)}</span>`;
  }

  /** Signed money amount, e.g. "+€0,06" / "−€0,19". */
  _money(amount) {
    const currency = this._hass?.config?.currency;
    try {
      return new Intl.NumberFormat(lang(this._hass), {
        ...(currency ? { style: "currency", currency } : { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
        signDisplay: "exceptZero",
      }).format(amount);
    } catch (e) {
      return (amount >= 0 ? "+" : "−") + Math.abs(amount).toFixed(2);
    }
  }

  _total(amount, L) {
    return `
      <div class="footer" title="${esc(L.savingsHelp)}">
        <span>${esc(L.result)}</span>
        <span class="value ${amount >= 0 ? "good" : "bad"}">${this._money(amount)}</span>
      </div>`;
  }

  _timing(timing, L) {
    return `
      <div class="footer" title="${esc(L.timingHelp)}">
        <span>${esc(L.timing)}</span>
        <span class="value">${this._pct(timing.cheap)} ${esc(L.cheapHours)}<span class="sep">·</span>${this._pct(timing.expensive)} ${esc(L.expensiveHours)}</span>
      </div>`;
  }

  _row(color, name, you, market, higherIsBetter, amount) {
    // Percentage and money amount side by side on one line below the price.
    const parts = [
      this._diff(you, market, higherIsBetter),
      amount != null ? `<span class="${amount >= 0 ? "good" : "bad"}">${this._money(amount)}</span>` : "",
    ].filter(Boolean);
    const sub = parts.length ? `<span class="diff">${parts.join('<span class="sep">·</span>')}</span>` : "";
    return `
      <div class="row">
        <div class="name"><span class="dot" style="background:${esc(color)}"></span>${esc(name)}</div>
        <div class="you">${this._fmt(you)}${sub}</div>
        <div class="market">${this._fmt(market)}</div>
      </div>`;
  }

  _render() {
    if (!this.shadowRoot || !this._config) return;
    const c = this._config;
    const L = c.labels || {};
    const r = this._result;
    const money = c.show_savings !== false;
    const marketHelp = r?.surcharged ? `${L.marketHelp}, ${L.surchargeHelp}` : L.marketHelp;
    const body = !r
      ? `<div class="loading">${this._waited >= 10 && L.needPicker ? esc(L.needPicker) : "…"}</div>`
      : `
        <div class="row head">
          <div></div>
          <div class="you" title="${esc(L.youHelp)}">${esc(L.you)}</div>
          <div class="market" title="${esc(marketHelp)}">${esc(L.market)}</div>
        </div>
        ${this._row(c.colors?.import, L.imp, r.importPaid, r.importMarket, false, money ? r.savings?.import : null)}
        ${r.hasExport ? this._row(c.colors?.export, L.exp, r.exportPaid, r.exportMarket, true, money ? r.savings?.export : null) : ""}
        ${money && r.savings?.total != null ? this._total(r.savings.total, L) : ""}
        ${r.timing ? this._timing(r.timing, L) : ""}`;
    this.shadowRoot.innerHTML = `
      <style>
        ha-card { height: 100%; }
        .card-header { padding: 16px 16px 0; font-size: var(--ha-card-header-font-size, 24px);
          font-weight: var(--ha-font-weight-normal, 400); line-height: 32px;
          color: var(--ha-card-header-color, var(--primary-text-color)); }
        .content { padding: 12px 16px 16px; }
        .row { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) minmax(0, 1fr);
          gap: 8px; align-items: baseline; padding: 6px 0; }
        .row + .row { border-top: 1px solid var(--divider-color); }
        .head { font-size: var(--ha-font-size-s, 12px); color: var(--secondary-text-color); padding-top: 0; }
        .head > div { cursor: help; }
        .name { display: flex; align-items: center; gap: 8px; min-width: 0; }
        .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
        .you { font-weight: var(--ha-font-weight-medium, 500); text-align: end; }
        .market { color: var(--secondary-text-color); text-align: end; }
        .diff { display: block; font-size: var(--ha-font-size-s, 12px); font-weight: 400; white-space: nowrap; }
        .sep { margin: 0 6px; color: var(--secondary-text-color); }
        .good { color: var(--success-color, #43a047); }
        .bad { color: var(--error-color, #db4437); }
        .loading { color: var(--secondary-text-color); }
        .footer { display: flex; justify-content: space-between; align-items: baseline; gap: 8px;
          margin-top: 6px; padding-top: 10px; border-top: 1px solid var(--divider-color); cursor: help; }
        .footer .value { font-weight: var(--ha-font-weight-medium, 500); text-align: end; }
      </style>
      <ha-card>
        ${c.title ? `<div class="card-header">${esc(c.title)}</div>` : ""}
        <div class="content">${body}</div>
      </ha-card>`;
  }
}

/* ------------------------------------------------------------------------ *
 * Cheap and expensive hours card
 *
 * The cheapest and most expensive hours of a day as bars, from the integration
 * (the same hours as the binary sensors; past days are calculated from the
 * recorded prices). Hovering over a block shows the price of that hour. The day
 * follows the Energy date picker. Shown on the Energy dashboard above the
 * average price card, and available for other dashboards.
 * ------------------------------------------------------------------------ */

/** Runs of consecutive hours, from a list of hour starts (ms). */
function hourRuns(hours) {
  const out = [];
  for (const t of [...hours].sort((a, b) => a - b)) {
    const last = out[out.length - 1];
    if (last && last[1] === t) last[1] = t + HOUR;
    else out.push([t, t + HOUR]);
  }
  return out;
}

/** Average price of the hours of a run ([start, end] in ms); null without known prices. */
function runAverage(prices, run) {
  const values = [];
  for (let t = run[0]; t < run[1]; t += HOUR) {
    const v = prices.get(t);
    if (typeof v === "number" && Number.isFinite(v)) values.push(v);
  }
  return values.length ? values.reduce((a, b) => a + b, 0) / values.length : null;
}

/** Local midnight at the end of the day that starts at `day` (23 to 25 hours later). */
function nextMidnight(day) {
  return localMidnight(day + 1.5 * DAY);
}

/**
 * The day an hours card shows for the selected date range: today when it is
 * in the range, otherwise the last day of the range.
 */
function shownDay(start, end, now = Date.now()) {
  const s = start ? start.getTime() : localMidnight(now);
  const e = end ? end.getTime() : Math.max(now, s) + 1;
  const today = localMidnight(now);
  if (today >= localMidnight(s) && today < e) return today;
  return localMidnight(Math.max(s, e - 1));
}

/** Average price per hour (hour start -> price) of [timestamp, price] points. */
function hourlyPrices(points) {
  const w = durations(points, HOUR);
  const sums = new Map();
  points.forEach(([t, v], i) => {
    const h = Math.floor(t / HOUR) * HOUR;
    const b = sums.get(h) || { sum: 0, weight: 0 };
    b.sum += v * w[i];
    b.weight += w[i];
    sums.set(h, b);
  });
  const out = new Map();
  for (const [h, b] of sums) if (b.weight > 0) out.set(h, b.sum / b.weight);
  return out;
}

/** Cheapest and most expensive hours (starts, ms) of one day from its hourly prices. */
function dayHours(prices, cheapestCount, expensiveCount) {
  const points = [...prices].sort((a, b) => a[0] - b[0]);
  const cheap = extremeHourSet(points, cheapestCount);
  const dear = extremeHourSet(points, expensiveCount, true, cheap);
  const sorted = (set) => [...set].sort((a, b) => a - b);
  return { cheapest: sorted(cheap), expensive: sorted(dear) };
}

class EnergyPriceHoursCard extends (globalThis.HTMLElement ?? class {}) {
  setConfig(config) {
    this._config = config || {};
    if (!this.shadowRoot) this.attachShadow({ mode: "open" });
    this._render();
    if (this.isConnected) this._subscribe();
  }

  set hass(hass) {
    const first = !this._hass;
    this._hass = hass;
    if (first) this._load();
    if (this.isConnected) this._subscribe();
  }

  get hass() {
    return this._hass;
  }

  connectedCallback() {
    clearInterval(this._timer);
    clearInterval(this._tick);
    // New prices arrive in the afternoon; the "now" line moves every minute.
    this._timer = setInterval(() => this._load(), 5 * 60000);
    this._tick = setInterval(() => !this._hovering && this._render(), 60000);
    this._load();
    this._subscribe();
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    clearInterval(this._tick);
    clearTimeout(this._retry);
    clearTimeout(this._again);
    this._unsub?.();
    this._unsub = undefined;
  }

  getCardSize() {
    return 3;
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }

  static getStubConfig() {
    return {};
  }

  /** Follow the Energy date picker (the day that is shown changes with it). */
  _subscribe() {
    if (this._unsub || !this._hass || !this._config) return;
    if (!this._config.labels) {
      // Added by hand to a dashboard: fill in the rest like on the Energy dashboard.
      this._autoConfig();
      return;
    }
    const collection = collectionOf(this._hass, this._config.collection_key);
    if (!collection?.subscribe) {
      // No date picker (yet): show today and look again for a while.
      clearTimeout(this._retry);
      this._waited = (this._waited || 0) + 1;
      if (this._waited < 20) this._retry = setTimeout(() => this._subscribe(), 500);
      return;
    }
    this._unsub = collection.subscribe((data) => this._select(data));
  }

  async _autoConfig() {
    if (this._autoPending) return;
    this._autoPending = true;
    try {
      const own = this._config;
      this._config = await standaloneConfig(
        this._hass,
        (found, key, L) => ({ ...hoursCard(found, key, L), hide_when_off: false }),
        own
      );
      this._render();
      this._subscribe();
      this._loadPrices();
    } catch (e) {
      console.warn(TAG, "could not set up the hours card", e);
    } finally {
      this._autoPending = false;
    }
  }

  _select(data) {
    const day = shownDay(data?.start, data?.end);
    if (day === this._day) return;
    this._day = day;
    this._loadPrices();
    this._render();
  }

  async _load() {
    if (!this._hass) return;
    try {
      this._data = await this._hass.callWS({ type: "energy_price_graph/hours" });
    } catch (e) {
      this._data = null;
    }
    this._render();
    this._loadPrices();
    // No hours yet (for example just after a restart): look again after a minute.
    const d = this._data;
    clearTimeout(this._again);
    if (d && (d.cheapest_count > 0 || d.expensive_count > 0) && !(d.cheapest?.length || d.expensive?.length)) {
      this._again = setTimeout(() => this._load(), 60000);
    }
  }

  /** Recorded hourly prices of the shown day, for the prices in the tooltip and for past days. */
  async _loadPrices() {
    const entity = this._config?.import_entity;
    const day = this._day ?? localMidnight();
    if (!entity || !this._hass?.callWS) return;
    this._stats ??= new Map();
    const cached = this._stats.get(day);
    if (cached && Date.now() - cached.at < 15 * 60000) return;
    this._stats.set(day, { at: Date.now(), prices: cached?.prices || new Map() });
    try {
      const res = await this._hass.callWS({
        type: "recorder/statistics_during_period",
        start_time: new Date(day).toISOString(),
        end_time: new Date(nextMidnight(day)).toISOString(),
        statistic_ids: [entity],
        period: "hour",
        types: ["mean"],
      });
      const prices = new Map();
      for (const row of res?.[entity] || []) {
        const t = toMs(row.start);
        if (Number.isFinite(t) && typeof row.mean === "number") prices.set(t, row.mean);
      }
      this._stats.set(day, { at: Date.now(), prices });
    } catch (e) {
      /* no recorded prices: the tooltip then only has the time */
    }
    this._render();
  }

  /** Price per hour of a day: recorded, with the upcoming prices on top for today and later. */
  _prices(day, end) {
    const out = new Map(this._stats?.get(day)?.prices || []);
    const entity = this._config?.import_entity;
    if (!entity || !this._hass || day < localMidnight()) return out;
    const source = forecastEntity(OPT.forecastImport, entity);
    if (!source) return out;
    const points = forecastFor(this._hass, source, () => this._render()).filter(([t]) => t >= day && t < end);
    if (!points.length) return out;
    const factor = forecastScale(points, Number(this._hass.states?.[entity]?.state));
    for (const [h, v] of hourlyPrices(points)) out.set(h, v * factor);
    return out;
  }

  /** Hours of the shown day: from the integration for today and later, calculated for past days. */
  _hoursOf(d, day, end, prices) {
    if (day >= localMidnight()) {
      const of = (k) => (d?.[k] || []).map((h) => Date.parse(h)).filter((t) => Number.isFinite(t) && t >= day && t < end);
      return { cheapest: of("cheapest"), expensive: of("expensive") };
    }
    return dayHours(prices, d?.cheapest_count || 0, d?.expensive_count || 0);
  }

  _labels() {
    const own = this._config?.labels;
    return own || (this._hass ? labels(this._hass) : LABELS.en);
  }

  /** Time of day in the user's format (Settings → Profile → Time format). */
  _time(t) {
    const format = this._hass?.locale?.time_format;
    const hour12 = format === "12" ? true : format === "24" ? false : undefined;
    return new Intl.DateTimeFormat(lang(this._hass), { hour: "numeric", minute: "2-digit", hour12 }).format(
      new Date(t)
    );
  }

  /** Like _time, but midnight at the end of a day is 24:00 in a 24-hour format. */
  _end(t) {
    const text = this._time(t);
    return /^0?0[:.]00$/.test(text) ? "24:00" : text;
  }

  _span([start, end]) {
    return `${this._time(start)} – ${this._end(end)}`;
  }

  _price(entity, value) {
    const attributes = this._hass?.states?.[entity]?.attributes;
    return formatPrice(this._hass, { state: String(value), attributes });
  }

  _render() {
    if (!this.shadowRoot || !this._config) return;
    const L = this._labels();
    const c = colors();
    const col = { cheapest: this._config.colors?.cheapest || c.good, expensive: this._config.colors?.expensive || c.warn };
    const d = this._data;
    const kinds = ["cheapest", "expensive"].filter((k) => d && d[`${k}_count`] > 0);
    // On the Energy dashboard the card disappears when both sliders are 0.
    this.style.display = !kinds.length && this._config.hide_when_off && this._data !== undefined ? "none" : "";
    const now = Date.now();
    const today = localMidnight(now);
    const start = this._day ?? today;
    const end = nextMidnight(start);
    const isToday = start === today;
    const prices = this._prices(start, end);
    const hours = this._hoursOf(d, start, end, prices);
    this._shown = { start, end, prices, hours: { cheapest: new Set(hours.cheapest), expensive: new Set(hours.expensive) } };
    const span = end - start;
    const pos = (t) => `${((Math.min(Math.max(t, start), end) - start) / span) * 100}%`;
    let body;
    if (!d || !kinds.length) {
      body = `<div class="muted">${esc(L.noHours)}</div>`;
    } else {
      const rows = kinds.map((k) => {
        const runs = hourRuns(hours[k]);
        const blocks = runs
          .map((r) => `<i style="left:${pos(r[0])};width:calc(${pos(r[1])} - ${pos(r[0])});background:${esc(col[k])}"></i>`)
          .join("");
        const entity = this._config?.import_entity;
        const spans = runs
          .map((r) => {
            const avg = entity ? runAverage(prices, r) : null;
            return avg == null ? this._span(r) : `${this._span(r)} (${L.avgShort || "avg."} ${this._price(entity, avg)})`;
          })
          .join(", ");
        return `
          <div class="label"><span>${esc(L[k])}</span><span class="muted spans">${esc(spans)}</span></div>
          <div class="bar" data-k="${k}">${blocks}<em class="hl"></em>${isToday ? `<b style="left:${pos(now)}"></b>` : ""}</div>`;
      });
      const tomorrow = isToday
        ? kinds
            .map((k) => {
              const runs = hourRuns((d[k] || []).map((h) => Date.parse(h)).filter((t) => t >= end));
              if (!runs.length) return "";
              const spans = runs.map((r) => this._span(r)).join(", ");
              return `<span><span class="dot" style="background:${esc(col[k])}"></span>${esc(spans)}</span>`;
            })
            .filter(Boolean)
        : [];
      const anyShown = kinds.some((k) => hours[k].length);
      const axis = [0, 6, 12, 18, 24]
        .map((h) => `<span>${esc(h === 24 ? this._end(end) : this._time(start + (h / 24) * span))}</span>`)
        .join("");
      const caption = isToday
        ? ""
        : `<div class="muted day">${esc(
            new Intl.DateTimeFormat(lang(this._hass), { weekday: "long", day: "numeric", month: "long" }).format(new Date(start))
          )}</div>`;
      body = anyShown
        ? `${caption}${rows.join("")}<div class="axis">${axis}</div>`
        : `${caption}<div class="muted">${esc(isToday && d.reason && L.noForecast ? L.noForecast : L.noHours)}</div>`;
      if (tomorrow.length) {
        body += `<div class="tomorrow"><div class="muted">${esc(L.tomorrow)}</div><div class="items">${tomorrow.join("")}</div></div>`;
      }
    }
    const title = this._config.title ?? L.hoursTitle;
    this.shadowRoot.innerHTML = `
      <style>
        ha-card { height: 100%; }
        .card-header { padding: 16px 16px 0; font-size: var(--ha-card-header-font-size, 24px);
          font-weight: var(--ha-font-weight-normal, 400); line-height: 32px;
          color: var(--ha-card-header-color, var(--primary-text-color)); }
        .content { padding: 12px 16px 16px; position: relative; }
        .day { margin-bottom: 6px; text-transform: capitalize; }
        .label { display: flex; justify-content: space-between; gap: 8px; margin: 4px 0 6px; }
        .spans { text-align: right; }
        .label + .bar, .bar { margin-bottom: 10px; }
        .bar { position: relative; height: 24px; border-radius: 6px; overflow: hidden; touch-action: pan-y;
          background: var(--secondary-background-color, rgba(127,127,127,0.15)); }
        .bar i { position: absolute; top: 0; bottom: 0; }
        .bar b { position: absolute; top: 0; bottom: 0; width: 2px; margin-left: -1px;
          background: var(--primary-text-color); pointer-events: none; }
        .hl { position: absolute; top: 0; bottom: 0; display: none; pointer-events: none;
          background: rgba(255,255,255,0.25); }
        .axis { display: flex; justify-content: space-between; color: var(--secondary-text-color);
          font-size: var(--ha-font-size-s, 12px); }
        .muted { color: var(--secondary-text-color); }
        .tomorrow { display: flex; gap: 16px; align-items: baseline; margin-top: 10px;
          padding-top: 10px; border-top: 1px solid var(--divider-color); }
        .items { flex: 1; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }
        .items > span { display: inline-flex; align-items: center; gap: 6px; }
        .dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
        .tip { position: absolute; display: none; z-index: 1; pointer-events: none; white-space: nowrap;
          padding: 6px 10px; border-radius: 8px; font-size: var(--ha-font-size-s, 12px); line-height: 16px;
          background: var(--card-background-color, #1c1c1c); color: var(--primary-text-color);
          border: 1px solid var(--divider-color); box-shadow: 0 2px 8px rgba(0,0,0,0.3); }
        .tip b { font-weight: var(--ha-font-weight-medium, 500); }
      </style>
      <ha-card>
        ${title ? `<div class="card-header">${esc(title)}</div>` : ""}
        <div class="content">${body}<div class="tip"></div></div>
      </ha-card>`;
    this._wire(col);
  }

  /** Show the price of the hour under the pointer when hovering over a coloured block. */
  _wire(col) {
    const root = this.shadowRoot;
    const tip = root.querySelector(".tip");
    const host = root.querySelector(".content");
    const { start, end, prices, hours } = this._shown;
    const entity = this._config?.import_entity;
    const span = end - start;
    const bars = [...root.querySelectorAll(".bar")];
    bars.forEach((bar) => {
      const hl = bar.querySelector(".hl");
      const hide = () => {
        tip.style.display = "none";
        hl.style.display = "none";
        this._hovering = false;
      };
      const show = (ev) => {
        const rect = bar.getBoundingClientRect();
        if (!rect.width) return;
        const ratio = Math.min(Math.max((ev.clientX - rect.left) / rect.width, 0), 0.9999);
        const hour = Math.floor((start + ratio * span) / HOUR) * HOUR;
        const kind = bar.dataset.k;
        if (!hours[kind].has(hour)) return hide();
        this._hovering = true;
        hl.style.left = `${((hour - start) / span) * 100}%`;
        hl.style.width = `${(HOUR / span) * 100}%`;
        hl.style.display = "block";
        const price = prices.get(hour);
        tip.innerHTML =
          `<span class="dot" style="display:inline-block;background:${esc(col[kind])};margin-right:6px"></span>` +
          `<b>${esc(this._time(hour))} – ${esc(this._end(hour + HOUR))}</b>` +
          (price == null || !entity ? "" : ` · ${esc(this._price(entity, price))}`);
        tip.style.display = "block";
        const box = host.getBoundingClientRect();
        const half = tip.offsetWidth / 2;
        const x = Math.min(Math.max(ev.clientX - box.left, half), Math.max(half, box.width - half));
        tip.style.left = `${x - half}px`;
        // Below the bars (over the time axis), so the time ranges above them stay readable.
        const last = bars[bars.length - 1].getBoundingClientRect();
        tip.style.top = `${last.bottom - box.top + 4}px`;
      };
      bar.addEventListener("pointermove", show);
      bar.addEventListener("pointerdown", show);
      bar.addEventListener("pointerleave", hide);
      bar.addEventListener("pointercancel", hide);
    });
  }
}

/* ------------------------------------------------------------------------ *
 * Water costs card
 *
 * Consumption, price and costs of the water source from the Energy settings
 * for the selected period, next to the period before it, with the costs per
 * day and, for the current month, what the month is expected to cost. The
 * costs come from the cost statistic of the source; without one they are the
 * consumption times the price (a fixed price per m³, or the average of a price
 * sensor). Follows the Energy date picker.
 * ------------------------------------------------------------------------ */

const WATER_CARD = "energy-price-water-card";

function waterCard(collectionKey, L) {
  return {
    type: `custom:${WATER_CARD}`,
    title: L.waterTitle,
    collection_key: collectionKey,
    labels: L,
  };
}

/** Unit of the water statistics in the Energy dashboard: m³, or ft³ for imperial. */
function waterUnit(hass) {
  return hass?.config?.unit_system?.length === "km" ? "m³" : "ft³";
}

/** Water sources of the energy prefs: statistic ids and the price, if one is set. */
function waterSources(prefs, info) {
  const costs = info?.cost_sensors || {};
  const out = [];
  for (const src of prefs?.energy_sources || []) {
    if (src.type !== "water" || !src.stat_energy_from) continue;
    out.push({
      energy: src.stat_energy_from,
      cost: src.stat_cost || costs[src.stat_energy_from] || null,
      fixed: typeof src.number_energy_price === "number" ? src.number_energy_price : null,
      priceEntity: src.entity_energy_price || null,
    });
  }
  return out;
}

/** Sum of the `change` of statistic rows; null without rows. */
function sumChange(rows) {
  if (!Array.isArray(rows)) return null;
  let sum = 0;
  let any = false;
  for (const r of rows) {
    if (typeof r?.change === "number" && Number.isFinite(r.change)) {
      sum += r.change;
      any = true;
    }
  }
  return any ? sum : null;
}

/**
 * Consumption, costs and price of one period. `stats` maps a statistic id to
 * its rows, `prices` maps a price sensor to its average over the period.
 */
function waterPeriod(stats, sources, prices = {}) {
  let volume = null;
  let cost = null;
  let fallback = null;
  for (const s of sources) {
    const v = sumChange(stats[s.energy]);
    if (v != null) volume = (volume || 0) + v;
    const price = s.fixed ?? prices[s.priceEntity] ?? null;
    if (fallback == null) fallback = price;
    let c = s.cost ? sumChange(stats[s.cost]) : null;
    if (c == null && v != null && price != null) c = v * price;
    if (c != null) cost = (cost || 0) + c;
  }
  const price = volume > 0 && cost != null ? cost / volume : fallback;
  return { volume, cost, price };
}

/** Whether a period is one calendar month (start on the 1st, ends within that month). */
function monthPeriod(start, end, now = Date.now()) {
  const d = new Date(start);
  if (d.getDate() !== 1 || localMidnight(start) !== start) return false;
  const next = new Date(d.getFullYear(), d.getMonth() + 1, 1).getTime();
  return (end ?? now) <= next;
}

/**
 * The period before the selected one: the calendar month before a month, else
 * as long as the period. A period that is not over yet (this month, today) is
 * compared with the same part of the previous one, so the figures are fair.
 */
function previousPeriod(start, end, now = Date.now()) {
  let prev;
  if (monthPeriod(start, end, now)) {
    const d = new Date(start);
    prev = { start: new Date(d.getFullYear(), d.getMonth() - 1, 1).getTime(), end: start };
  } else {
    const length = Math.max((end ?? now) - start, DAY);
    prev = { start: start - length, end: start };
  }
  if (end != null && end <= now) return { ...prev, partial: false };
  const cut = prev.start + Math.max(now - start, 0);
  return cut < prev.end ? { start: prev.start, end: cut, partial: true } : { ...prev, partial: false };
}

/** Costs per day over the part of the period that has passed (at least one day). */
function costPerDay(cost, start, end, now = Date.now()) {
  if (cost == null) return null;
  return cost / Math.max((Math.min(end ?? now, now) - start) / DAY, 1);
}

/** What the current month will cost at the pace so far; null for other periods or the first day. */
function monthOutlook(cost, start, end, now = Date.now()) {
  if (cost == null || !monthPeriod(start, end, now)) return null;
  const d = new Date(start);
  const next = new Date(d.getFullYear(), d.getMonth() + 1, 1).getTime();
  if (now < start || now >= next) return null;
  const elapsed = (now - start) / DAY;
  if (elapsed < 1) return null;
  return (cost / elapsed) * Math.round((next - start) / DAY);
}

class EnergyPriceWaterCard extends (globalThis.HTMLElement ?? class {}) {
  setConfig(config) {
    this._config = config || {};
    if (!this.shadowRoot) this.attachShadow({ mode: "open" });
    this._render();
    if (this._data && this._hass) this._update(this._data);
  }

  set hass(hass) {
    this._hass = hass;
    if (this.isConnected) this._subscribe();
  }

  get hass() {
    return this._hass;
  }

  connectedCallback() {
    this._subscribe();
  }

  disconnectedCallback() {
    this._unsub?.();
    this._unsub = undefined;
    clearTimeout(this._retry);
    clearTimeout(this._retryLoad);
  }

  getCardSize() {
    return 4;
  }

  getGridOptions() {
    return { columns: 12, min_columns: 6, rows: "auto" };
  }

  static getStubConfig() {
    return {};
  }

  _subscribe() {
    if (this._unsub || !this._hass || !this._config) return;
    if (!this._config.labels) {
      this._autoConfig();
      return;
    }
    const collection = collectionOf(this._hass, this._config.collection_key);
    if (!collection?.subscribe) {
      clearTimeout(this._retry);
      this._waited = (this._waited || 0) + 1;
      if (this._waited === 10) this._render();
      this._retry = setTimeout(() => this._subscribe(), 500);
      return;
    }
    this._waited = 0;
    this._unsub = collection.subscribe((data) => this._update(data));
  }

  async _autoConfig() {
    if (this._autoPending) return;
    this._autoPending = true;
    try {
      this._config = await standaloneConfig(this._hass, (found, key, L) => waterCard(key, L), this._config);
      this._render();
      this._subscribe();
    } catch (e) {
      console.warn(TAG, "could not set up the water costs card", e);
    } finally {
      this._autoPending = false;
    }
  }

  async _update(data) {
    this._data = data;
    clearTimeout(this._retryLoad);
    const run = (this._run = (this._run || 0) + 1);
    const sources = waterSources(data?.prefs, data?.info);
    let result = { sources: sources.length };
    let failed = false;
    if (sources.length && data?.start) {
      try {
        result = { ...result, ...(await this._compute(data, sources)) };
      } catch (e) {
        failed = true;
        console.warn(TAG, "could not load the water statistics, retrying", e);
      }
    }
    if (run !== this._run) return; // a newer period was selected meanwhile
    this._result = result;
    this._render();
    // The recorder may still be starting (e.g. right after a restart): retry.
    if (failed && this.isConnected) this._retryLoad = setTimeout(() => this._data && this._update(this._data), 15000);
  }

  async _compute(data, sources) {
    const now = Date.now();
    const start = data.start.getTime();
    const end = data.end ? data.end.getTime() : null;
    const prev = previousPeriod(start, end, now);
    const ids = [...new Set(sources.flatMap((s) => [s.energy, s.cost]).filter(Boolean))];
    const res = await this._hass.callWS({
      type: "recorder/statistics_during_period",
      start_time: new Date(prev.start).toISOString(),
      ...(end && { end_time: new Date(end).toISOString() }),
      statistic_ids: ids,
      period: marketPeriod(prev.start, end),
      types: ["change"],
      units: { volume: waterUnit(this._hass) },
    });
    const within = (from, to) => {
      const out = {};
      for (const id of ids) {
        out[id] = (res?.[id] || []).filter((r) => {
          const t = toMs(r.start);
          return t >= from && (to == null || t < to);
        });
      }
      return out;
    };
    // A price sensor is only needed when a source has neither a cost statistic nor a fixed price.
    const sensors = [...new Set(sources.filter((s) => s.priceEntity && s.fixed == null).map((s) => s.priceEntity))];
    let currentPrices = {};
    let previousPrices = {};
    if (sensors.length) {
      try {
        currentPrices = await marketAverages(this._hass, data.start, data.end, sensors);
        previousPrices = await marketAverages(this._hass, new Date(prev.start), new Date(prev.end), sensors);
      } catch (e) {
        console.warn(TAG, "could not load the water price", e);
      }
    }
    const current = waterPeriod(within(start, null), sources, currentPrices);
    const previous = waterPeriod(within(prev.start, prev.end), sources, previousPrices);
    return {
      current,
      previous,
      start,
      end,
      month: monthPeriod(start, end, now),
      partial: prev.partial,
      previousStart: prev.start,
      perDay: costPerDay(current.cost, start, end, now),
      outlook: monthOutlook(current.cost, start, end, now),
    };
  }

  _number(value, digits) {
    return new Intl.NumberFormat(lang(this._hass), {
      minimumFractionDigits: digits,
      maximumFractionDigits: digits,
    }).format(value);
  }

  _volume(value) {
    if (value == null) return "—";
    const digits = Math.abs(value) < 10 ? 2 : 1;
    return `${this._number(value, digits)} ${waterUnit(this._hass)}`;
  }

  _price(value) {
    if (value == null) return "—";
    return `${this._number(value, 2)} ${currencySymbol(this._hass)}/${waterUnit(this._hass)}`.replace(/\s+/g, " ");
  }

  _cost(value, signed = false) {
    if (value == null) return "—";
    const currency = this._hass?.config?.currency;
    try {
      return new Intl.NumberFormat(lang(this._hass), {
        ...(currency ? { style: "currency", currency } : { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
        ...(signed && { signDisplay: "exceptZero" }),
      }).format(value);
    } catch (e) {
      return value.toFixed(2);
    }
  }

  /** Change compared with the previous period; more water or higher costs is shown as worse. */
  _change(now, before, money = false) {
    if (now == null || before == null || !before) return "";
    const rel = (now - before) / Math.abs(before);
    if (Math.abs(rel) < 0.0005) return "";
    const parts = [
      new Intl.NumberFormat(lang(this._hass), {
        style: "percent",
        maximumFractionDigits: 1,
        signDisplay: "exceptZero",
      }).format(rel),
    ];
    if (money) parts.push(this._cost(now - before, true));
    return `<span class="diff ${rel > 0 ? "bad" : "good"}">${parts.join('<span class="sep">·</span>')}</span>`;
  }

  _names(r, L) {
    if (r.month) {
      const month = (t) =>
        new Intl.DateTimeFormat(lang(this._hass), { month: "long" }).format(new Date(t));
      return [month(r.start), month(r.previousStart)];
    }
    return [L.waterThis, L.waterPrevious];
  }

  _row(name, now, before, text, money = false) {
    return `
      <div class="row">
        <div class="name">${esc(name)}</div>
        <div class="you">${text(now)}${this._change(now, before, money)}</div>
        <div class="market">${text(before)}</div>
      </div>`;
  }

  _footer(name, value, help) {
    return `
      <div class="footer"${help ? ` title="${esc(help)}"` : ""}>
        <span>${esc(name)}</span><span class="value">${this._cost(value)}</span>
      </div>`;
  }

  _render() {
    if (!this.shadowRoot || !this._config) return;
    const c = this._config;
    const L = c.labels || {};
    const r = this._result;
    let body;
    if (!r) {
      body = `<div class="loading">${this._waited >= 10 && L.needPicker ? esc(L.needPicker) : "…"}</div>`;
    } else if (!r.sources) {
      body = `<div class="loading">${esc(L.noWater)}</div>`;
    } else if (!r.current) {
      body = `<div class="loading">…</div>`;
    } else {
      const [now, before] = this._names(r, L);
      const cur = r.current;
      const prev = r.previous;
      body = `
        <div class="row head">
          <div></div><div class="you">${esc(now)}</div><div class="market">${esc(before)}</div>
        </div>
        ${r.partial && L.waterSameDays ? `<div class="note">${esc(L.waterSameDays)}</div>` : ""}
        ${this._row(L.waterUse, cur.volume, prev.volume, (v) => this._volume(v))}
        ${this._row(L.waterPrice, cur.price, prev.price, (v) => this._price(v))}
        ${this._row(L.waterCosts, cur.cost, prev.cost, (v) => this._cost(v), true)}
        ${cur.cost == null ? `<div class="loading">${esc(L.waterNoPrice)}</div>` : ""}
        ${r.perDay != null ? this._footer(L.waterPerDay, r.perDay) : ""}
        ${r.outlook != null ? this._footer(L.waterExpected, r.outlook, L.waterExpectedHelp) : ""}`;
    }
    this.shadowRoot.innerHTML = `
      <style>
        ha-card { height: 100%; }
        .card-header { padding: 16px 16px 0; font-size: var(--ha-card-header-font-size, 24px);
          font-weight: var(--ha-font-weight-normal, 400); line-height: 32px;
          color: var(--ha-card-header-color, var(--primary-text-color)); }
        .content { padding: 12px 16px 16px; }
        .row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) minmax(0, 1fr);
          gap: 8px; align-items: baseline; padding: 6px 0; }
        .row + .row { border-top: 1px solid var(--divider-color); }
        .head { font-size: var(--ha-font-size-s, 12px); color: var(--secondary-text-color); padding-top: 0;
          text-transform: capitalize; }
        .you { font-weight: var(--ha-font-weight-medium, 500); text-align: end; }
        .market { color: var(--secondary-text-color); text-align: end; }
        .diff { display: block; font-size: var(--ha-font-size-s, 12px); font-weight: 400; white-space: nowrap; }
        .sep { margin: 0 6px; color: var(--secondary-text-color); }
        .good { color: var(--success-color, #43a047); }
        .bad { color: var(--error-color, #db4437); }
        .loading { color: var(--secondary-text-color); padding-top: 4px; }
        .note { color: var(--secondary-text-color); font-size: var(--ha-font-size-s, 12px); padding-bottom: 4px; }
        .footer { display: flex; justify-content: space-between; align-items: baseline; gap: 8px;
          margin-top: 6px; padding-top: 10px; border-top: 1px solid var(--divider-color); }
        .footer[title] { cursor: help; }
        .footer .value { font-weight: var(--ha-font-weight-medium, 500); text-align: end; }
      </style>
      <ha-card>
        ${c.title ? `<div class="card-header">${esc(c.title)}</div>` : ""}
        <div class="content">${body}</div>
      </ha-card>`;
  }
}

/* ------------------------------------------------------------------------ *
 * Price graph card for other dashboards
 *
 * Builds the same statistics-graph card as on the Energy dashboard (with the
 * current price, upcoming prices and markers) and follows the Energy date
 * picker card of the dashboard it is on.
 * ------------------------------------------------------------------------ */

class EnergyPriceGraphCard extends (globalThis.HTMLElement ?? class {}) {
  setConfig(config) {
    this._config = config || {};
    this._card = null;
    this._build();
  }

  set hass(hass) {
    this._hass = hass;
    if (this._card) this._card.hass = hass;
    else this._build();
  }

  get hass() {
    return this._hass;
  }

  getCardSize() {
    return 5;
  }

  getGridOptions() {
    return { columns: "full", min_columns: 6, rows: "auto" };
  }

  static getStubConfig() {
    return { kind: "electricity" };
  }

  disconnectedCallback() {
    clearTimeout(this._hint);
  }

  async _build() {
    if (!this._hass || !this._config || this._building) return;
    this._building = true;
    const config = this._config;
    try {
      const gas = config.kind === "gas";
      const cfg = await standaloneConfig(
        this._hass,
        (found, key, L) => {
          if (gas) return found.gas ? gasCard(found.gas, key, L) : null;
          return found.imp || found.exp ? priceCard(found, key, L) : null;
        },
        null
      ).catch(() => null);
      if (config !== this._config) return; // changed meanwhile
      const L = labels(this._hass);
      if (!cfg || !cfg.type) {
        this._message(
          gas
            ? "Energy Price Graph: no gas price sensor in the Energy settings."
            : "Energy Price Graph: no electricity price sensor in the Energy settings."
        );
        return;
      }
      if (config.collection_key) cfg.collection_key = config.collection_key;
      if (config.title !== undefined) cfg.title = config.title;
      const helpers = await window.loadCardHelpers();
      const card = helpers.createCardElement(cfg);
      card.hass = this._hass;
      this.replaceChildren(card);
      this._card = card;
      // Hint when the dashboard has no Energy date picker card.
      clearTimeout(this._hint);
      this._hint = setTimeout(() => {
        if (!collectionOf(this._hass, cfg.collection_key)) {
          const p = document.createElement("div");
          p.style.cssText = "padding:8px 16px;color:var(--secondary-text-color);font-size:12px";
          p.textContent = L.needPicker;
          this.append(p);
        }
      }, 5000);
    } catch (e) {
      console.warn(TAG, "could not build the price graph card", e);
    } finally {
      this._building = false;
    }
  }

  _message(text) {
    const card = document.createElement("ha-card");
    card.style.cssText = "display:block;padding:16px;color:var(--secondary-text-color)";
    card.textContent = text;
    this.replaceChildren(card);
  }
}

/**
 * Define the card on a registry. The frontend may swap window.customElements
 * for a scoped-registry polyfill after this module ran, so this is called for
 * every registry we hook; each gets its own subclass because a constructor
 * can only be registered once.
 */
function defineAverageCard(reg, get) {
  const cards = [
    [AVG_CARD, EnergyPriceAverageCard],
    [HOURS_CARD, EnergyPriceHoursCard],
    [WATER_CARD, EnergyPriceWaterCard],
    [GRAPH_CARD, EnergyPriceGraphCard],
  ];
  for (const [tag, base] of cards) {
    try {
      if (!get.call(reg, tag)) reg.define(tag, class extends base {});
    } catch (e) {
      console.warn(TAG, `could not define ${tag}`, e);
    }
  }
}

/** Offer the cards in the "Add card" dialog of a dashboard. */
function registerCardPicker() {
  const w = globalThis.window;
  if (!w || w.__energyPriceGraphCards) return;
  w.__energyPriceGraphCards = true;
  w.customCards = w.customCards || [];
  const docs = "https://github.com/Gtolsma/HA-Energy-Price-Graph#-cards-on-your-own-dashboards";
  w.customCards.push(
    {
      type: GRAPH_CARD,
      name: "Energy Price Graph",
      description: "Electricity or gas price with upcoming prices and markers, like on the Energy dashboard.",
      documentationURL: docs,
    },
    {
      type: AVG_CARD,
      name: "Energy Price Graph: average price",
      description: "What you paid and received per kWh compared with the market.",
      documentationURL: docs,
    },
    {
      type: HOURS_CARD,
      name: "Energy Price Graph: cheap and expensive hours",
      description: "Today's cheapest and most expensive hours as bars.",
      documentationURL: docs,
    },
    {
      type: WATER_CARD,
      name: "Energy Price Graph: water costs",
      description: "Water consumption, price and costs compared with the previous period.",
      documentationURL: docs,
    }
  );
}

/* Start: hook the registry now and whenever the frontend replaces it. */
if (globalThis.window?.customElements) {
  registerCardPicker();
  installRegistryHooks();
  // Keep checking for a replaced registry for a while after start-up.
  const hookTimer = setInterval(installRegistryHooks, 100);
  setTimeout(() => clearInterval(hookTimer), 120000);
}

